insert into public.study_author_questions (authored_id,topic_id,number,subject,text,options,answer,explanation)
select authored_id,topic_id,number,subject,text,options,answer,explanation
from jsonb_to_recordset($questions$[{"authored_id":"porcentagem-01","topic_id":"porcentagem","number":1,"subject":"Matemática","text":"Uma mochila de R$ 200 recebe desconto de 15%. Qual é o preço final?","options":["170 reais","30 reais","190 reais","230 reais"],"answer":"A","explanation":"O desconto é 30. Multiplicando 200 por 0,85, o preço final é R$ 170."},{"authored_id":"porcentagem-02","topic_id":"porcentagem","number":2,"subject":"Matemática","text":"Uma turma tem 40 alunos, dos quais 10 usam bicicleta. Qual é o percentual que usa bicicleta?","options":["10%","25%","40%","75%"],"answer":"B","explanation":"Divida a parte pelo total: 10/40 = 0,25 = 25%. O fator comum não altera a razão."},{"authored_id":"porcentagem-03","topic_id":"porcentagem","number":3,"subject":"Matemática","text":"Após um aumento de 20%, uma mensalidade passou a R$ 120. Quanto custava antes?","options":["96 reais","144 reais","100 reais","80 reais"],"answer":"C","explanation":"O preço final corresponde a 1,20 vezes o inicial: 120/1,20 = 100."},{"authored_id":"porcentagem-04","topic_id":"porcentagem","number":4,"subject":"Matemática","text":"R$ 100 sofrem aumento de 10% e depois desconto de 10%. Qual é o valor final?","options":["100 reais","90 reais","110 reais","99 reais"],"answer":"D","explanation":"Os fatores se multiplicam: 100 × 1,10 × 0,90 = 99. As bases dos percentuais são diferentes."},{"authored_id":"porcentagem-05","topic_id":"porcentagem","number":5,"subject":"Matemática","text":"Uma reserva caiu de 80 para 60 litros. Qual foi a redução percentual?","options":["25%","20%","30%","75%"],"answer":"A","explanation":"A redução é 20/80 do valor inicial: 0,25, ou 25%."},{"authored_id":"porcentagem-06","topic_id":"porcentagem","number":6,"subject":"Matemática","text":"Um investimento de R$ 500 rende juros simples de 2% ao mês por 3 meses. Qual é o juro total?","options":["10 reais","30 reais","60 reais","530 reais"],"answer":"B","explanation":"J = capital × taxa × tempo = 500 × 0,02 × 3 = 30."},{"authored_id":"porcentagem-07","topic_id":"porcentagem","number":7,"subject":"Matemática","text":"Um produto custa R$ 250. Um desconto de 20% e outro de 10%, sucessivos, dão qual preço final?","options":["175 reais","200 reais","180 reais","225 reais"],"answer":"C","explanation":"Preço final = 250 × 0,80 × 0,90 = 180. O desconto equivalente é 28%."},{"authored_id":"porcentagem-08","topic_id":"porcentagem","number":8,"subject":"Matemática","text":"Uma taxa passa de 10% para 15%. Quantos pontos percentuais ela aumenta?","options":["50 pontos percentuais","20 pontos percentuais","1,5 pontos percentuais","5 pontos percentuais"],"answer":"D","explanation":"Pontos percentuais são a diferença entre as taxas: 15 − 10 = 5."},{"authored_id":"porcentagem-09","topic_id":"porcentagem","number":9,"subject":"Matemática","text":"Uma loja vendeu 30 peças, atingindo 60% da meta. Qual era a meta?","options":["50 peças","18 peças","40 peças","60 peças"],"answer":"A","explanation":"Se 0,60 × meta = 30, então meta = 30/0,60 = 50."},{"authored_id":"porcentagem-10","topic_id":"porcentagem","number":10,"subject":"Matemática","text":"Um salário de R$ 1000 aumenta 5%. Qual é o valor do aumento?","options":["1.050 reais","50 reais","5 reais","100 reais"],"answer":"B","explanation":"A questão pede somente o aumento: 1000 × 0,05 = 50, e não o salário final."},{"authored_id":"regra-de-tres-01","topic_id":"regra-de-tres","number":1,"subject":"Matemática","text":"3 cadernos custam R$ 24. Mantendo o preço unitário, quanto custam 5 cadernos?","options":["40 reais","32 reais","15 reais","120 reais"],"answer":"A","explanation":"Cada caderno custa R$ 8. Logo 5 × 8 = 40."},{"authored_id":"regra-de-tres-02","topic_id":"regra-de-tres","number":2,"subject":"Matemática","text":"4 trabalhadores fazem um serviço em 12 dias. Com 6 trabalhadores de mesma produtividade, quantos dias são necessários?","options":["18 dias","8 dias","6 dias","10 dias"],"answer":"B","explanation":"A relação é inversa: trabalhadores × dias é constante. Portanto 4 × 12/6 = 8 dias."},{"authored_id":"regra-de-tres-03","topic_id":"regra-de-tres","number":3,"subject":"Matemática","text":"Uma viagem de 180 km é feita a 60 km/h constantes. Quanto tempo ela dura?","options":["2 horas","4 horas","3 horas","6 horas"],"answer":"C","explanation":"Tempo = distância/velocidade = 180/60 = 3."},{"authored_id":"regra-de-tres-04","topic_id":"regra-de-tres","number":4,"subject":"Matemática","text":"Em um mapa de escala 1:100.000, duas cidades distam 3 cm. Qual é a distância real em quilômetros?","options":["30 km","0,3 km","300 km","3 km"],"answer":"D","explanation":"Cada centímetro representa 100.000 cm = 1 km. Multiplique a medida do mapa por 1 km."},{"authored_id":"regra-de-tres-05","topic_id":"regra-de-tres","number":5,"subject":"Matemática","text":"Uma receita para 4 pessoas usa 200 g de arroz. Quanto usar para 10 pessoas?","options":["500 g","80 g","400 g","1.000 g"],"answer":"A","explanation":"A quantidade é diretamente proporcional: 200 × 10/4 = 500 g."},{"authored_id":"regra-de-tres-06","topic_id":"regra-de-tres","number":6,"subject":"Matemática","text":"2 máquinas produzem 80 peças em 4 horas. Quantas peças 3 máquinas iguais produzem em 6 horas?","options":["120 peças","180 peças","160 peças","240 peças"],"answer":"B","explanation":"A produção varia com máquinas e horas: 80 × (3/2) × (6/4) = 180 peças."},{"authored_id":"regra-de-tres-07","topic_id":"regra-de-tres","number":7,"subject":"Matemática","text":"Uma torneira despeja 6 litros por minuto. Quantos litros despeja em 15 minutos?","options":["21 litros","60 litros","90 litros","120 litros"],"answer":"C","explanation":"Volume = vazão × tempo = 6 × 15 = 90 litros."},{"authored_id":"regra-de-tres-08","topic_id":"regra-de-tres","number":8,"subject":"Matemática","text":"Um carro consome 1 litro a cada 12 km. Quantos litros usa para percorrer 240 km?","options":["12 litros","24 litros","2.880 litros","20 litros"],"answer":"D","explanation":"Consumo = 240/12 = 20 litros, mantendo as condições de rendimento."},{"authored_id":"regra-de-tres-09","topic_id":"regra-de-tres","number":9,"subject":"Matemática","text":"Uma peça de 60 cm é desenhada na escala 1:5. Qual é o comprimento no desenho?","options":["12 cm","300 cm","5 cm","30 cm"],"answer":"A","explanation":"Medida desenhada = medida real/5 = 60/5 = 12 cm."},{"authored_id":"regra-de-tres-10","topic_id":"regra-de-tres","number":10,"subject":"Matemática","text":"A 40 km/h, uma entrega leva 3 horas. A 60 km/h no mesmo percurso, quanto tempo levará?","options":["4,5 horas","2 horas","1,5 horas","3 horas"],"answer":"B","explanation":"Para distância fixa, velocidade e tempo são inversos: 40 × 3/60 = 2 horas."},{"authored_id":"funcoes-01","topic_id":"funcoes","number":1,"subject":"Matemática","text":"Uma corrida custa R$ 5 fixos mais R$ 2 por km. Qual é o custo de 10 km?","options":["25 reais","20 reais","15 reais","50 reais"],"answer":"A","explanation":"C(x) = 5 + 2x. Substituindo x = 10, temos 25."},{"authored_id":"funcoes-02","topic_id":"funcoes","number":2,"subject":"Matemática","text":"Na função f(x) = 2x + 3, qual é f(4)?","options":["8","11","9","5"],"answer":"B","explanation":"Substitua x por 4: 2 × 4 + 3 = 11."},{"authored_id":"funcoes-03","topic_id":"funcoes","number":3,"subject":"Matemática","text":"Qual é a raiz de f(x) = 3x − 6?","options":["3","-2","2","6"],"answer":"C","explanation":"Na raiz, f(x)=0: 3x = 6, portanto x = 2."},{"authored_id":"funcoes-04","topic_id":"funcoes","number":4,"subject":"Matemática","text":"Um reservatório tem 100 litros e perde 5 litros por minuto. Após 8 minutos, qual é seu volume?","options":["140 litros","92 litros","5 litros","60 litros"],"answer":"D","explanation":"V(t)=100−5t. Logo V(8)=100−40=60."},{"authored_id":"funcoes-05","topic_id":"funcoes","number":5,"subject":"Matemática","text":"Qual é o coeficiente angular da reta que passa por (0, 2) e (3, 8)?","options":["2","3","6","8"],"answer":"A","explanation":"A taxa de variação é Δy/Δx = 6/3 = 2. O valor inicial não muda a inclinação."},{"authored_id":"funcoes-06","topic_id":"funcoes","number":6,"subject":"Matemática","text":"Qual é o maior valor de f(x) = −x² + 4x?","options":["2","4","8","-4"],"answer":"B","explanation":"A parábola tem concavidade para baixo. O vértice está em x=2; f(2)=4."},{"authored_id":"funcoes-07","topic_id":"funcoes","number":7,"subject":"Matemática","text":"Qual é o menor valor de f(x) = (x − 3)² + 2?","options":["0","3","2","-2"],"answer":"C","explanation":"Um quadrado é não negativo. Seu mínimo é zero quando x=3, então o valor mínimo da função é 2."},{"authored_id":"funcoes-08","topic_id":"funcoes","number":8,"subject":"Matemática","text":"Na função f(x) = 5 − 2x, qual é a ordenada na origem?","options":["-2","-5","2,5","5"],"answer":"D","explanation":"A ordenada na origem é f(0) = 5; não é a raiz nem o coeficiente de x."},{"authored_id":"funcoes-09","topic_id":"funcoes","number":9,"subject":"Matemática","text":"Uma população segue P(t) = 100 × 2ᵗ. Qual é P(3)?","options":["800 indivíduos","300 indivíduos","600 indivíduos","200 indivíduos"],"answer":"A","explanation":"2³=8. Portanto P(3)=100 × 8=800."},{"authored_id":"funcoes-10","topic_id":"funcoes","number":10,"subject":"Matemática","text":"Uma loja tem receita R(x)=20x e custo C(x)=100+10x. Quantas unidades precisa vender para receita e custo serem iguais?","options":["5 unidades","10 unidades","20 unidades","100 unidades"],"answer":"B","explanation":"Iguale as funções: 20x=100+10x. Assim 10x=100 e x=10."},{"authored_id":"geometria-01","topic_id":"geometria","number":1,"subject":"Matemática","text":"Um terreno retangular mede 8 m por 5 m. Qual é sua área?","options":["40 m²","26 m²","13 m²","80 m²"],"answer":"A","explanation":"Área do retângulo = base × altura = 8 × 5 = 40 m²."},{"authored_id":"geometria-02","topic_id":"geometria","number":2,"subject":"Matemática","text":"Um triângulo tem base 12 cm e altura perpendicular de 5 cm. Qual é sua área?","options":["60 cm²","30 cm²","17 cm²","120 cm²"],"answer":"B","explanation":"Área = base × altura/2 = 12 × 5/2 = 30 cm²."},{"authored_id":"geometria-03","topic_id":"geometria","number":3,"subject":"Matemática","text":"Um quadrado tem lado 6 m. Qual é seu perímetro?","options":["36 m","12 m","24 m","6 m"],"answer":"C","explanation":"Perímetro soma os quatro lados: 4 × 6 = 24 m."},{"authored_id":"geometria-04","topic_id":"geometria","number":4,"subject":"Matemática","text":"Um círculo tem raio 3 cm. Usando π=3, qual é sua área?","options":["18 cm²","12 cm²","54 cm²","27 cm²"],"answer":"D","explanation":"Área=πr²=3 × (3)²=27 cm²."},{"authored_id":"geometria-05","topic_id":"geometria","number":5,"subject":"Matemática","text":"Uma caixa mede 2 m por 3 m por 4 m. Qual é seu volume?","options":["24 m³","9 m³","12 m³","48 m³"],"answer":"A","explanation":"Volume do paralelepípedo = 2 × 3 × 4 = 24 m³."},{"authored_id":"geometria-06","topic_id":"geometria","number":6,"subject":"Matemática","text":"Um cubo de aresta 2 cm tem qual área total?","options":["8 cm²","24 cm²","4 cm²","12 cm²"],"answer":"B","explanation":"São seis faces quadradas: 6 × (2)² = 24 cm²."},{"authored_id":"geometria-07","topic_id":"geometria","number":7,"subject":"Matemática","text":"Uma escada forma um triângulo retângulo com catetos 3 m e 4 m. Qual é a hipotenusa?","options":["7 m","25 m","5 m","6 m"],"answer":"C","explanation":"Pelo teorema de Pitágoras: h²=(3)²+(4)²=25. Logo h=5 m."},{"authored_id":"geometria-08","topic_id":"geometria","number":8,"subject":"Matemática","text":"Um cilindro tem raio 2 cm e altura 5 cm. Adotando π=3, qual é seu volume?","options":["30 cm³","20 cm³","120 cm³","60 cm³"],"answer":"D","explanation":"Volume=πr²h=3 × (2)² × 5 = 60 cm³."},{"authored_id":"geometria-09","topic_id":"geometria","number":9,"subject":"Matemática","text":"Uma planta tem 2 m² de área real. Quantos centímetros quadrados equivalem a essa área?","options":["20.000 cm²","200 cm²","2.000 cm²","20 cm²"],"answer":"A","explanation":"1 m² = (100 cm)² = 10.000 cm². Logo 2 m² = 20000 cm²."},{"authored_id":"geometria-10","topic_id":"geometria","number":10,"subject":"Matemática","text":"Dois quadrados semelhantes têm lados 2 cm e 6 cm. Quantas vezes a área do maior é a do menor?","options":["3 vezes","9 vezes","6 vezes","27 vezes"],"answer":"B","explanation":"A razão dos lados é 3; a razão das áreas é o quadrado dessa razão: 3²=9."},{"authored_id":"estatistica-01","topic_id":"estatistica","number":1,"subject":"Matemática","text":"As notas são 2, 4 e 6. Qual é a média?","options":["4","12","3","6"],"answer":"A","explanation":"Some os valores e divida por 3: 12/3 = 4."},{"authored_id":"estatistica-02","topic_id":"estatistica","number":2,"subject":"Matemática","text":"Ordenando os valores 8, 2, 5, 1 e 9, qual é a mediana?","options":["2","5","8","9"],"answer":"B","explanation":"A lista ordenada é 1, 2, 5, 8, 9. O terceiro termo é 5."},{"authored_id":"estatistica-03","topic_id":"estatistica","number":3,"subject":"Matemática","text":"Qual é a mediana dos valores 2, 4, 8 e 10?","options":["4","8","6","24"],"answer":"C","explanation":"Com quatro valores ordenados, calcule a média dos dois centrais: (4+8)/2=6."},{"authored_id":"estatistica-04","topic_id":"estatistica","number":4,"subject":"Matemática","text":"Na lista 1, 3, 3, 5, 7, qual é a moda?","options":["1","5","7","3"],"answer":"D","explanation":"A moda é o valor mais frequente. 3 aparece duas vezes; os demais aparecem uma vez."},{"authored_id":"estatistica-05","topic_id":"estatistica","number":5,"subject":"Matemática","text":"As temperaturas variaram entre 12 e 20 graus. Qual é a amplitude?","options":["8 graus","32 graus","16 graus","20 graus"],"answer":"A","explanation":"Amplitude = máximo − mínimo = 20−12=8."},{"authored_id":"estatistica-06","topic_id":"estatistica","number":6,"subject":"Matemática","text":"Uma avaliação de nota 6 tem peso 1 e outra de nota 9 tem peso 2. Qual é a média ponderada?","options":["7,5","8","15","24"],"answer":"B","explanation":"A média ponderada é (6×1+9×2)/(1+2)=8."},{"authored_id":"estatistica-07","topic_id":"estatistica","number":7,"subject":"Matemática","text":"Uma pesquisa registra 20 votos para A, 30 para B e 50 para C. Qual é a frequência relativa de B?","options":["20%","50%","30%","60%"],"answer":"C","explanation":"B tem 30 de 100 votos: 30/100 = 30%."},{"authored_id":"estatistica-08","topic_id":"estatistica","number":8,"subject":"Matemática","text":"Vendas foram 10 na segunda, 15 na terça e 25 na quarta. Qual é o total?","options":["25 vendas","40 vendas","15 vendas","50 vendas"],"answer":"D","explanation":"Some as três frequências: 10+15+25=50."},{"authored_id":"estatistica-09","topic_id":"estatistica","number":9,"subject":"Matemática","text":"A média de quatro valores é 5. Ao acrescentar 10, qual é a nova média?","options":["6","7,5","5","10"],"answer":"A","explanation":"A soma anterior era 4 × 5=20. A nova média é (20+10)/5=6."},{"authored_id":"estatistica-10","topic_id":"estatistica","number":10,"subject":"Matemática","text":"Qual é a média de 2, 2, 2 e 10?","options":["2","4","10","16"],"answer":"B","explanation":"A soma é 16 e há quatro valores. A média é 4; o valor alto a desloca acima da mediana."},{"authored_id":"probabilidade-01","topic_id":"probabilidade","number":1,"subject":"Matemática","text":"Uma urna tem 3 bolas azuis e 2 vermelhas. Qual é a probabilidade de retirar uma azul?","options":["60%","40%","30%","50%"],"answer":"A","explanation":"São 3 partes azuis em 5 partes totais: 3/5 = 60%. Todas as bolas têm a mesma chance."},{"authored_id":"probabilidade-02","topic_id":"probabilidade","number":2,"subject":"Matemática","text":"Uma caixa tem 1 bola verde e 4 amarelas. Qual é a chance de retirar uma bola que não seja verde?","options":["20%","80%","25%","75%"],"answer":"B","explanation":"O evento complementar tem probabilidade 1−1/5=4/5=80%."},{"authored_id":"probabilidade-03","topic_id":"probabilidade","number":3,"subject":"Matemática","text":"Uma urna tem 2 bolas pretas e 2 brancas. Com reposição, qual é a chance de retirar duas pretas?","options":["50%","75%","25%","100%"],"answer":"C","explanation":"Com reposição, os sorteios são independentes. A chance é 1/2 × 1/2 = 1/4 = 25%."},{"authored_id":"probabilidade-04","topic_id":"probabilidade","number":4,"subject":"Matemática","text":"Uma urna tem 3 bolas azuis e 2 vermelhas. Sem reposição, quantos objetos restam após a primeira retirada?","options":["5 bolas","3 bolas","2 bolas","4 bolas"],"answer":"D","explanation":"Sem reposição, o total diminui uma unidade: 5−1=4. Esse é o denominador do segundo sorteio."},{"authored_id":"probabilidade-05","topic_id":"probabilidade","number":5,"subject":"Matemática","text":"Um cartão é sorteado entre os números de 1 a 10. Qual é a chance de obter número par?","options":["50%","10%","25%","75%"],"answer":"A","explanation":"Há 5 pares em 10 cartões: 5/10=1/2=50%."},{"authored_id":"probabilidade-06","topic_id":"probabilidade","number":6,"subject":"Matemática","text":"Uma loja oferece 3 camisetas e 4 calças. Quantas combinações de uma camiseta e uma calça existem?","options":["7 combinações","12 combinações","9 combinações","24 combinações"],"answer":"B","explanation":"Pelo princípio multiplicativo: 3 × 4 = 12."},{"authored_id":"probabilidade-07","topic_id":"probabilidade","number":7,"subject":"Matemática","text":"Uma senha tem dois algarismos, cada um escolhido entre 0 e 3, com repetição permitida. Quantas senhas existem, incluindo as que começam por zero?","options":["8 senhas","12 senhas","16 senhas","4 senhas"],"answer":"C","explanation":"Cada posição tem 4 opções. Multiplique as quantidades: 4²=16."},{"authored_id":"probabilidade-08","topic_id":"probabilidade","number":8,"subject":"Matemática","text":"Um dado honesto de seis faces é lançado 1 vez(es). Qual é a probabilidade de sair 6 no primeiro lançamento?","options":["1/3","1/2","5/6","1/6"],"answer":"D","explanation":"Há um resultado favorável entre seis resultados equiprováveis. O número total de lançamentos não muda a chance do primeiro."},{"authored_id":"probabilidade-09","topic_id":"probabilidade","number":9,"subject":"Matemática","text":"3 estudantes disputam uma bolsa com chances iguais. Quantos resultados favoráveis existem ao evento “Ana é a escolhida”, se Ana participa?","options":["1 resultado","3 resultado","2 resultado","0 resultado"],"answer":"A","explanation":"O evento contém somente Ana. A probabilidade seria 1 dividido pelo total de participantes, mas a pergunta pede a contagem favorável."},{"authored_id":"probabilidade-10","topic_id":"probabilidade","number":10,"subject":"Matemática","text":"Uma roda tem 4 setores iguais: 1 vermelhos, 1 verdes e 2 azuis. Qual é a chance de parar no vermelho ou verde?","options":["25%","50%","75%","100%"],"answer":"B","explanation":"Os eventos são mutuamente exclusivos: (k+k)/(4k)=1/2=50%."},{"authored_id":"porcentagem-11","topic_id":"porcentagem","number":11,"subject":"Matemática","text":"Uma mochila de R$ 400 recebe desconto de 15%. Qual é o preço final?","options":["60 reais","380 reais","340 reais","460 reais"],"answer":"C","explanation":"O desconto é 60. Multiplicando 400 por 0,85, o preço final é R$ 340."},{"authored_id":"porcentagem-12","topic_id":"porcentagem","number":12,"subject":"Matemática","text":"Uma turma tem 80 alunos, dos quais 20 usam bicicleta. Qual é o percentual que usa bicicleta?","options":["10%","40%","75%","25%"],"answer":"D","explanation":"Divida a parte pelo total: 10/40 = 0,25 = 25%. O fator comum não altera a razão."},{"authored_id":"porcentagem-13","topic_id":"porcentagem","number":13,"subject":"Matemática","text":"Após um aumento de 20%, uma mensalidade passou a R$ 240. Quanto custava antes?","options":["200 reais","192 reais","288 reais","160 reais"],"answer":"A","explanation":"O preço final corresponde a 1,20 vezes o inicial: 240/1,20 = 200."},{"authored_id":"porcentagem-14","topic_id":"porcentagem","number":14,"subject":"Matemática","text":"R$ 200 sofrem aumento de 10% e depois desconto de 10%. Qual é o valor final?","options":["200 reais","198 reais","180 reais","220 reais"],"answer":"B","explanation":"Os fatores se multiplicam: 200 × 1,10 × 0,90 = 198. As bases dos percentuais são diferentes."},{"authored_id":"porcentagem-15","topic_id":"porcentagem","number":15,"subject":"Matemática","text":"Uma reserva caiu de 160 para 120 litros. Qual foi a redução percentual?","options":["20%","30%","25%","75%"],"answer":"C","explanation":"A redução é 20/80 do valor inicial: 0,25, ou 25%."},{"authored_id":"porcentagem-16","topic_id":"porcentagem","number":16,"subject":"Matemática","text":"Um investimento de R$ 1000 rende juros simples de 2% ao mês por 3 meses. Qual é o juro total?","options":["20 reais","120 reais","1.060 reais","60 reais"],"answer":"D","explanation":"J = capital × taxa × tempo = 1000 × 0,02 × 3 = 60."},{"authored_id":"porcentagem-17","topic_id":"porcentagem","number":17,"subject":"Matemática","text":"Um produto custa R$ 500. Um desconto de 20% e outro de 10%, sucessivos, dão qual preço final?","options":["360 reais","350 reais","400 reais","450 reais"],"answer":"A","explanation":"Preço final = 500 × 0,80 × 0,90 = 360. O desconto equivalente é 28%."},{"authored_id":"porcentagem-18","topic_id":"porcentagem","number":18,"subject":"Matemática","text":"Uma taxa passa de 20% para 30%. Quantos pontos percentuais ela aumenta?","options":["50 pontos percentuais","10 pontos percentuais","40 pontos percentuais","3 pontos percentuais"],"answer":"B","explanation":"Pontos percentuais são a diferença entre as taxas: 30 − 20 = 10."},{"authored_id":"porcentagem-19","topic_id":"porcentagem","number":19,"subject":"Matemática","text":"Uma loja vendeu 60 peças, atingindo 60% da meta. Qual era a meta?","options":["36 peças","80 peças","100 peças","120 peças"],"answer":"C","explanation":"Se 0,60 × meta = 60, então meta = 60/0,60 = 100."},{"authored_id":"porcentagem-20","topic_id":"porcentagem","number":20,"subject":"Matemática","text":"Um salário de R$ 2000 aumenta 5%. Qual é o valor do aumento?","options":["2.100 reais","10 reais","200 reais","100 reais"],"answer":"D","explanation":"A questão pede somente o aumento: 2000 × 0,05 = 100, e não o salário final."},{"authored_id":"regra-de-tres-11","topic_id":"regra-de-tres","number":11,"subject":"Matemática","text":"6 cadernos custam R$ 48. Mantendo o preço unitário, quanto custam 10 cadernos?","options":["64 reais","30 reais","80 reais","240 reais"],"answer":"C","explanation":"Cada caderno custa R$ 8. Logo 10 × 8 = 80."},{"authored_id":"regra-de-tres-12","topic_id":"regra-de-tres","number":12,"subject":"Matemática","text":"8 trabalhadores fazem um serviço em 12 dias. Com 12 trabalhadores de mesma produtividade, quantos dias são necessários?","options":["18 dias","6 dias","10 dias","8 dias"],"answer":"D","explanation":"A relação é inversa: trabalhadores × dias é constante. Portanto 4 × 12/6 = 8 dias."},{"authored_id":"regra-de-tres-13","topic_id":"regra-de-tres","number":13,"subject":"Matemática","text":"Uma viagem de 360 km é feita a 60 km/h constantes. Quanto tempo ela dura?","options":["6 horas","4 horas","8 horas","12 horas"],"answer":"A","explanation":"Tempo = distância/velocidade = 360/60 = 6."},{"authored_id":"regra-de-tres-14","topic_id":"regra-de-tres","number":14,"subject":"Matemática","text":"Em um mapa de escala 1:100.000, duas cidades distam 6 cm. Qual é a distância real em quilômetros?","options":["60 km","6 km","0,6 km","600 km"],"answer":"B","explanation":"Cada centímetro representa 100.000 cm = 1 km. Multiplique a medida do mapa por 1 km."},{"authored_id":"regra-de-tres-15","topic_id":"regra-de-tres","number":15,"subject":"Matemática","text":"Uma receita para 4 pessoas usa 400 g de arroz. Quanto usar para 10 pessoas?","options":["160 g","800 g","1.000 g","2.000 g"],"answer":"C","explanation":"A quantidade é diretamente proporcional: 400 × 10/4 = 1000 g."},{"authored_id":"regra-de-tres-16","topic_id":"regra-de-tres","number":16,"subject":"Matemática","text":"4 máquinas produzem 80 peças em 4 horas. Quantas peças 6 máquinas iguais produzem em 6 horas?","options":["120 peças","160 peças","240 peças","180 peças"],"answer":"D","explanation":"A produção varia com máquinas e horas: 80 × (3/2) × (6/4) = 180 peças."},{"authored_id":"regra-de-tres-17","topic_id":"regra-de-tres","number":17,"subject":"Matemática","text":"Uma torneira despeja 12 litros por minuto. Quantos litros despeja em 15 minutos?","options":["180 litros","42 litros","120 litros","240 litros"],"answer":"A","explanation":"Volume = vazão × tempo = 12 × 15 = 180 litros."},{"authored_id":"regra-de-tres-18","topic_id":"regra-de-tres","number":18,"subject":"Matemática","text":"Um carro consome 1 litro a cada 12 km. Quantos litros usa para percorrer 480 km?","options":["24 litros","40 litros","48 litros","5.760 litros"],"answer":"B","explanation":"Consumo = 480/12 = 40 litros, mantendo as condições de rendimento."},{"authored_id":"regra-de-tres-19","topic_id":"regra-de-tres","number":19,"subject":"Matemática","text":"Uma peça de 120 cm é desenhada na escala 1:5. Qual é o comprimento no desenho?","options":["600 cm","10 cm","24 cm","60 cm"],"answer":"C","explanation":"Medida desenhada = medida real/5 = 120/5 = 24 cm."},{"authored_id":"regra-de-tres-20","topic_id":"regra-de-tres","number":20,"subject":"Matemática","text":"A 80 km/h, uma entrega leva 3 horas. A 120 km/h no mesmo percurso, quanto tempo levará?","options":["4,5 horas","1,5 horas","3 horas","2 horas"],"answer":"D","explanation":"Para distância fixa, velocidade e tempo são inversos: 40 × 3/60 = 2 horas."},{"authored_id":"funcoes-11","topic_id":"funcoes","number":11,"subject":"Matemática","text":"Uma corrida custa R$ 10 fixos mais R$ 2 por km. Qual é o custo de 20 km?","options":["40 reais","30 reais","50 reais","100 reais"],"answer":"C","explanation":"C(x) = 10 + 2x. Substituindo x = 20, temos 50."},{"authored_id":"funcoes-12","topic_id":"funcoes","number":12,"subject":"Matemática","text":"Na função f(x) = 4x + 3, qual é f(4)?","options":["16","11","13","19"],"answer":"D","explanation":"Substitua x por 4: 4 × 4 + 3 = 19."},{"authored_id":"funcoes-13","topic_id":"funcoes","number":13,"subject":"Matemática","text":"Qual é a raiz de f(x) = 3x − 12?","options":["4","6","-4","12"],"answer":"A","explanation":"Na raiz, f(x)=0: 3x = 12, portanto x = 4."},{"authored_id":"funcoes-14","topic_id":"funcoes","number":14,"subject":"Matemática","text":"Um reservatório tem 200 litros e perde 5 litros por minuto. Após 8 minutos, qual é seu volume?","options":["240 litros","160 litros","192 litros","10 litros"],"answer":"B","explanation":"V(t)=200−5t. Logo V(8)=200−40=160."},{"authored_id":"funcoes-15","topic_id":"funcoes","number":15,"subject":"Matemática","text":"Qual é o coeficiente angular da reta que passa por (0, 4) e (3, 10)?","options":["3","6","2","10"],"answer":"C","explanation":"A taxa de variação é Δy/Δx = 6/3 = 2. O valor inicial não muda a inclinação."},{"authored_id":"funcoes-16","topic_id":"funcoes","number":16,"subject":"Matemática","text":"Qual é o maior valor de f(x) = −x² + 8x?","options":["4","32","-16","16"],"answer":"D","explanation":"A parábola tem concavidade para baixo. O vértice está em x=4; f(4)=16."},{"authored_id":"funcoes-17","topic_id":"funcoes","number":17,"subject":"Matemática","text":"Qual é o menor valor de f(x) = (x − 6)² + 2?","options":["2","0","6","-2"],"answer":"A","explanation":"Um quadrado é não negativo. Seu mínimo é zero quando x=6, então o valor mínimo da função é 2."},{"authored_id":"funcoes-18","topic_id":"funcoes","number":18,"subject":"Matemática","text":"Na função f(x) = 10 − 2x, qual é a ordenada na origem?","options":["-2","10","-10","5"],"answer":"B","explanation":"A ordenada na origem é f(0) = 10; não é a raiz nem o coeficiente de x."},{"authored_id":"funcoes-19","topic_id":"funcoes","number":19,"subject":"Matemática","text":"Uma população segue P(t) = 200 × 2ᵗ. Qual é P(3)?","options":["600 indivíduos","1.200 indivíduos","1.600 indivíduos","400 indivíduos"],"answer":"C","explanation":"2³=8. Portanto P(3)=200 × 8=1600."},{"authored_id":"funcoes-20","topic_id":"funcoes","number":20,"subject":"Matemática","text":"Uma loja tem receita R(x)=20x e custo C(x)=200+10x. Quantas unidades precisa vender para receita e custo serem iguais?","options":["10 unidades","40 unidades","200 unidades","20 unidades"],"answer":"D","explanation":"Iguale as funções: 20x=200+10x. Assim 10x=200 e x=20."},{"authored_id":"geometria-11","topic_id":"geometria","number":11,"subject":"Matemática","text":"Um terreno retangular mede 16 m por 5 m. Qual é sua área?","options":["52 m²","26 m²","80 m²","160 m²"],"answer":"C","explanation":"Área do retângulo = base × altura = 16 × 5 = 80 m²."},{"authored_id":"geometria-12","topic_id":"geometria","number":12,"subject":"Matemática","text":"Um triângulo tem base 24 cm e altura perpendicular de 5 cm. Qual é sua área?","options":["120 cm²","34 cm²","240 cm²","60 cm²"],"answer":"D","explanation":"Área = base × altura/2 = 24 × 5/2 = 60 cm²."},{"authored_id":"geometria-13","topic_id":"geometria","number":13,"subject":"Matemática","text":"Um quadrado tem lado 12 m. Qual é seu perímetro?","options":["48 m","144 m","24 m","12 m"],"answer":"A","explanation":"Perímetro soma os quatro lados: 4 × 12 = 48 m."},{"authored_id":"geometria-14","topic_id":"geometria","number":14,"subject":"Matemática","text":"Um círculo tem raio 6 cm. Usando π=3, qual é sua área?","options":["36 cm²","108 cm²","48 cm²","216 cm²"],"answer":"B","explanation":"Área=πr²=3 × (6)²=108 cm²."},{"authored_id":"geometria-15","topic_id":"geometria","number":15,"subject":"Matemática","text":"Uma caixa mede 4 m por 3 m por 4 m. Qual é seu volume?","options":["18 m³","24 m³","48 m³","96 m³"],"answer":"C","explanation":"Volume do paralelepípedo = 4 × 3 × 4 = 48 m³."},{"authored_id":"geometria-16","topic_id":"geometria","number":16,"subject":"Matemática","text":"Um cubo de aresta 4 cm tem qual área total?","options":["64 cm²","16 cm²","48 cm²","96 cm²"],"answer":"D","explanation":"São seis faces quadradas: 6 × (4)² = 96 cm²."},{"authored_id":"geometria-17","topic_id":"geometria","number":17,"subject":"Matemática","text":"Uma escada forma um triângulo retângulo com catetos 6 m e 8 m. Qual é a hipotenusa?","options":["10 m","14 m","100 m","12 m"],"answer":"A","explanation":"Pelo teorema de Pitágoras: h²=(6)²+(8)²=100. Logo h=10 m."},{"authored_id":"geometria-18","topic_id":"geometria","number":18,"subject":"Matemática","text":"Um cilindro tem raio 4 cm e altura 5 cm. Adotando π=3, qual é seu volume?","options":["120 cm³","240 cm³","40 cm³","480 cm³"],"answer":"B","explanation":"Volume=πr²h=3 × (4)² × 5 = 240 cm³."},{"authored_id":"geometria-19","topic_id":"geometria","number":19,"subject":"Matemática","text":"Uma planta tem 4 m² de área real. Quantos centímetros quadrados equivalem a essa área?","options":["400 cm²","4.000 cm²","40.000 cm²","40 cm²"],"answer":"C","explanation":"1 m² = (100 cm)² = 10.000 cm². Logo 4 m² = 40000 cm²."},{"authored_id":"geometria-20","topic_id":"geometria","number":20,"subject":"Matemática","text":"Dois quadrados semelhantes têm lados 4 cm e 12 cm. Quantas vezes a área do maior é a do menor?","options":["3 vezes","6 vezes","27 vezes","9 vezes"],"answer":"D","explanation":"A razão dos lados é 3; a razão das áreas é o quadrado dessa razão: 3²=9."},{"authored_id":"estatistica-11","topic_id":"estatistica","number":11,"subject":"Matemática","text":"As notas são 4, 8 e 12. Qual é a média?","options":["24","6","8","12"],"answer":"C","explanation":"Some os valores e divida por 3: 24/3 = 8."},{"authored_id":"estatistica-12","topic_id":"estatistica","number":12,"subject":"Matemática","text":"Ordenando os valores 16, 4, 10, 2 e 18, qual é a mediana?","options":["4","16","18","10"],"answer":"D","explanation":"A lista ordenada é 2, 4, 10, 16, 18. O terceiro termo é 10."},{"authored_id":"estatistica-13","topic_id":"estatistica","number":13,"subject":"Matemática","text":"Qual é a mediana dos valores 4, 8, 16 e 20?","options":["12","8","16","48"],"answer":"A","explanation":"Com quatro valores ordenados, calcule a média dos dois centrais: (8+16)/2=12."},{"authored_id":"estatistica-14","topic_id":"estatistica","number":14,"subject":"Matemática","text":"Na lista 2, 6, 6, 10, 14, qual é a moda?","options":["2","6","10","14"],"answer":"B","explanation":"A moda é o valor mais frequente. 6 aparece duas vezes; os demais aparecem uma vez."},{"authored_id":"estatistica-15","topic_id":"estatistica","number":15,"subject":"Matemática","text":"As temperaturas variaram entre 24 e 40 graus. Qual é a amplitude?","options":["64 graus","32 graus","16 graus","40 graus"],"answer":"C","explanation":"Amplitude = máximo − mínimo = 40−24=16."},{"authored_id":"estatistica-16","topic_id":"estatistica","number":16,"subject":"Matemática","text":"Uma avaliação de nota 12 tem peso 1 e outra de nota 18 tem peso 2. Qual é a média ponderada?","options":["15","30","48","16"],"answer":"D","explanation":"A média ponderada é (12×1+18×2)/(1+2)=16."},{"authored_id":"estatistica-17","topic_id":"estatistica","number":17,"subject":"Matemática","text":"Uma pesquisa registra 40 votos para A, 60 para B e 100 para C. Qual é a frequência relativa de B?","options":["30%","20%","50%","60%"],"answer":"A","explanation":"B tem 60 de 200 votos: 30/100 = 30%."},{"authored_id":"estatistica-18","topic_id":"estatistica","number":18,"subject":"Matemática","text":"Vendas foram 20 na segunda, 30 na terça e 50 na quarta. Qual é o total?","options":["50 vendas","100 vendas","80 vendas","30 vendas"],"answer":"B","explanation":"Some as três frequências: 20+30+50=100."},{"authored_id":"estatistica-19","topic_id":"estatistica","number":19,"subject":"Matemática","text":"A média de quatro valores é 10. Ao acrescentar 20, qual é a nova média?","options":["15","10","12","20"],"answer":"C","explanation":"A soma anterior era 4 × 10=40. A nova média é (40+20)/5=12."},{"authored_id":"estatistica-20","topic_id":"estatistica","number":20,"subject":"Matemática","text":"Qual é a média de 4, 4, 4 e 20?","options":["4","20","32","8"],"answer":"D","explanation":"A soma é 32 e há quatro valores. A média é 8; o valor alto a desloca acima da mediana."},{"authored_id":"probabilidade-11","topic_id":"probabilidade","number":11,"subject":"Matemática","text":"Uma urna tem 6 bolas azuis e 4 vermelhas. Qual é a probabilidade de retirar uma azul?","options":["40%","30%","60%","50%"],"answer":"C","explanation":"São 3 partes azuis em 5 partes totais: 3/5 = 60%. Todas as bolas têm a mesma chance."},{"authored_id":"probabilidade-12","topic_id":"probabilidade","number":12,"subject":"Matemática","text":"Uma caixa tem 2 bola verde e 8 amarelas. Qual é a chance de retirar uma bola que não seja verde?","options":["20%","25%","75%","80%"],"answer":"D","explanation":"O evento complementar tem probabilidade 1−1/5=4/5=80%."},{"authored_id":"probabilidade-13","topic_id":"probabilidade","number":13,"subject":"Matemática","text":"Uma urna tem 4 bolas pretas e 4 brancas. Com reposição, qual é a chance de retirar duas pretas?","options":["25%","50%","75%","100%"],"answer":"A","explanation":"Com reposição, os sorteios são independentes. A chance é 1/2 × 1/2 = 1/4 = 25%."},{"authored_id":"probabilidade-14","topic_id":"probabilidade","number":14,"subject":"Matemática","text":"Uma urna tem 6 bolas azuis e 4 vermelhas. Sem reposição, quantos objetos restam após a primeira retirada?","options":["10 bolas","9 bolas","6 bolas","4 bolas"],"answer":"B","explanation":"Sem reposição, o total diminui uma unidade: 10−1=9. Esse é o denominador do segundo sorteio."},{"authored_id":"probabilidade-15","topic_id":"probabilidade","number":15,"subject":"Matemática","text":"Um cartão é sorteado entre os números de 1 a 20. Qual é a chance de obter número par?","options":["10%","25%","50%","75%"],"answer":"C","explanation":"Há 10 pares em 20 cartões: 10/20=1/2=50%."},{"authored_id":"probabilidade-16","topic_id":"probabilidade","number":16,"subject":"Matemática","text":"Uma loja oferece 6 camisetas e 4 calças. Quantas combinações de uma camiseta e uma calça existem?","options":["10 combinações","18 combinações","48 combinações","24 combinações"],"answer":"D","explanation":"Pelo princípio multiplicativo: 6 × 4 = 24."},{"authored_id":"probabilidade-17","topic_id":"probabilidade","number":17,"subject":"Matemática","text":"Uma senha tem dois algarismos, cada um escolhido entre 0 e 4, com repetição permitida. Quantas senhas existem, incluindo as que começam por zero?","options":["25 senhas","10 senhas","20 senhas","5 senhas"],"answer":"A","explanation":"Cada posição tem 5 opções. Multiplique as quantidades: 5²=25."},{"authored_id":"probabilidade-18","topic_id":"probabilidade","number":18,"subject":"Matemática","text":"Um dado honesto de seis faces é lançado 2 vez(es). Qual é a probabilidade de sair 6 no primeiro lançamento?","options":["1/3","1/6","1/2","5/6"],"answer":"B","explanation":"Há um resultado favorável entre seis resultados equiprováveis. O número total de lançamentos não muda a chance do primeiro."},{"authored_id":"probabilidade-19","topic_id":"probabilidade","number":19,"subject":"Matemática","text":"6 estudantes disputam uma bolsa com chances iguais. Quantos resultados favoráveis existem ao evento “Ana é a escolhida”, se Ana participa?","options":["6 resultado","4 resultado","1 resultado","0 resultado"],"answer":"C","explanation":"O evento contém somente Ana. A probabilidade seria 1 dividido pelo total de participantes, mas a pergunta pede a contagem favorável."},{"authored_id":"probabilidade-20","topic_id":"probabilidade","number":20,"subject":"Matemática","text":"Uma roda tem 8 setores iguais: 2 vermelhos, 2 verdes e 4 azuis. Qual é a chance de parar no vermelho ou verde?","options":["25%","75%","100%","50%"],"answer":"D","explanation":"Os eventos são mutuamente exclusivos: (k+k)/(4k)=1/2=50%."},{"authored_id":"interpretacao-01","topic_id":"interpretacao","number":1,"subject":"Português","text":"Leia: “A biblioteca ampliou o horário; assim, estudantes que trabalham puderam frequentá-la.” Qual é a ideia central?","options":["A ampliação favoreceu o acesso de estudantes trabalhadores.","A biblioteca deixou de receber outros estudantes.","Os trabalhadores abandonaram o emprego.","O horário anterior era ilegal."],"answer":"A","explanation":"A relação entre a mudança de horário e a possibilidade de acesso aparece explicitamente no trecho."},{"authored_id":"interpretacao-02","topic_id":"interpretacao","number":2,"subject":"Português","text":"“Pedro levou um casaco ao ouvir a previsão de queda de temperatura.” O que se pode inferir?","options":["Já estava nevando.","Pedro considerou a possibilidade de frio.","Pedro trabalha na previsão do tempo.","A previsão estava errada."],"answer":"B","explanation":"Levar o casaco é uma preparação para o frio previsto; não comprova o estado do tempo nem a profissão do personagem."},{"authored_id":"interpretacao-03","topic_id":"interpretacao","number":3,"subject":"Português","text":"“O projeto é caro, porém necessário.” Qual é a relação marcada por “porém”?","options":["Causa.","Conclusão.","Oposição.","Condição."],"answer":"C","explanation":"Porém é adversativo: contrapõe a necessidade ao custo alto."},{"authored_id":"interpretacao-04","topic_id":"interpretacao","number":4,"subject":"Português","text":"“Choveu muito; portanto, a partida foi adiada.” Portanto introduz:","options":["Comparação.","Alternância.","Concessão.","Conclusão."],"answer":"D","explanation":"O adiamento é apresentado como consequência que se conclui da chuva."},{"authored_id":"interpretacao-05","topic_id":"interpretacao","number":5,"subject":"Português","text":"“Se você revisar o texto, encontrará o erro.” O primeiro segmento expressa:","options":["Condição.","Certeza de que a revisão ocorreu.","Conclusão.","Comparação."],"answer":"A","explanation":"Se introduz uma condição para o resultado previsto; não afirma que a ação aconteceu."},{"authored_id":"interpretacao-06","topic_id":"interpretacao","number":6,"subject":"Português","text":"“Feche a torneira enquanto escova os dentes.” Qual é a finalidade predominante?","options":["Narrar um acontecimento passado.","Orientar uma ação.","Descrever um personagem.","Definir um termo científico."],"answer":"B","explanation":"O verbo no imperativo instrui o leitor sobre uma atitude."},{"authored_id":"interpretacao-07","topic_id":"interpretacao","number":7,"subject":"Português","text":"“Que pontualidade! Você chegou uma hora depois.” Qual é o efeito da exclamação?","options":["Elogio literal à pontualidade.","Dúvida sobre a hora atual.","Ironia, pois o elogio aparente critica o atraso.","Descrição neutra da viagem."],"answer":"C","explanation":"A contradição entre pontualidade e atraso revela um sentido crítico oposto ao literal."},{"authored_id":"interpretacao-08","topic_id":"interpretacao","number":8,"subject":"Português","text":"“Joana entregou o livro a Clara. Esta começou a leitura.” A quem “esta” se refere?","options":["Joana.","Ao livro.","À leitura.","Clara."],"answer":"D","explanation":"O demonstrativo retoma a pessoa mencionada mais recentemente, Clara."},{"authored_id":"interpretacao-09","topic_id":"interpretacao","number":9,"subject":"Português","text":"“Poucos moradores participaram da reunião.” Qual alternativa mantém o sentido?","options":["Uma pequena quantidade de moradores participou.","Nenhum morador participou.","Todos participaram.","A maioria necessariamente participou."],"answer":"A","explanation":"Poucos indica quantidade reduzida, sem equivaler a nenhum ou todos."},{"authored_id":"interpretacao-10","topic_id":"interpretacao","number":10,"subject":"Português","text":"“A praça ganhou árvores e bancos. O espaço ficou mais acolhedor.” A segunda frase apresenta:","options":["Uma ordem de remoção dos bancos.","Uma avaliação do resultado das mudanças.","Uma condição anterior às mudanças.","Uma pergunta sem resposta."],"answer":"B","explanation":"Mais acolhedor avalia o efeito das intervenções descritas na frase anterior."},{"authored_id":"interpretacao-11","topic_id":"interpretacao","number":11,"subject":"Português","text":"Uma notícia informa local, data e consequências de uma enchente. Sua finalidade predominante é:","options":["Vender necessariamente um seguro.","Ensinar uma receita.","Informar sobre um acontecimento.","Criar uma regra gramatical."],"answer":"C","explanation":"Os dados sobre o acontecimento sustentam a função informativa do gênero notícia."},{"authored_id":"interpretacao-12","topic_id":"interpretacao","number":12,"subject":"Português","text":"“O aplicativo promete economia, mas exige assinatura cara.” Qual leitura é sustentada?","options":["O aplicativo é gratuito.","Todas as pessoas economizaram.","A assinatura não existe.","Há contraste entre a promessa e o custo exigido."],"answer":"D","explanation":"Mas contrapõe a promessa de economia ao custo; o trecho não comprova resultados universais."},{"authored_id":"interpretacao-13","topic_id":"interpretacao","number":13,"subject":"Português","text":"“A cidade acordou sob um cobertor de neblina.” A expressão “cobertor de neblina” é:","options":["Uma imagem figurada da neblina cobrindo a cidade.","Um tecido instalado sobre os prédios.","Uma definição técnica do clima.","Uma informação sobre roupas."],"answer":"A","explanation":"A metáfora aproxima a cobertura da neblina à de um cobertor, sem sentido literal."},{"authored_id":"interpretacao-14","topic_id":"interpretacao","number":14,"subject":"Português","text":"“O ônibus atrasou porque houve um acidente.” A oração com “porque” apresenta:","options":["A finalidade do atraso.","A causa do atraso.","Uma comparação entre ônibus.","Uma condição futura."],"answer":"B","explanation":"Porque explica o motivo que produziu o atraso."},{"authored_id":"interpretacao-15","topic_id":"interpretacao","number":15,"subject":"Português","text":"“Embora estivesse cansada, Luísa terminou a atividade.” O trecho destaca:","options":["O abandono da atividade.","A ausência de cansaço.","A realização apesar de uma dificuldade.","Uma dúvida sobre quem é Luísa."],"answer":"C","explanation":"Embora marca concessão: o cansaço não impediu a realização."},{"authored_id":"interpretacao-16","topic_id":"interpretacao","number":16,"subject":"Português","text":"Texto A defende ciclovias pela segurança. Texto B as defende pela redução de emissões. Qual comparação é correta?","options":["Os textos necessariamente se contradizem.","Ambos rejeitam ciclovias.","Ambos usam apenas o argumento econômico.","Os textos concordam com a medida, mas usam argumentos diferentes."],"answer":"D","explanation":"A conclusão comum é favorável às ciclovias; segurança e emissões são justificativas distintas."},{"authored_id":"interpretacao-17","topic_id":"interpretacao","number":17,"subject":"Português","text":"“Segundo a pesquisadora, o resultado ainda é preliminar.” Qual palavra limita a certeza?","options":["Preliminar.","Pesquisadora.","Resultado, por si só.","Segundo, como numeral."],"answer":"A","explanation":"Preliminar indica resultado inicial que ainda pode ser revisto, evitando leitura definitiva."},{"authored_id":"interpretacao-18","topic_id":"interpretacao","number":18,"subject":"Português","text":"“Precisamos de mais bibliotecas, pois elas ampliam o acesso à leitura.” Qual é a tese?","options":["A palavra pois.","Precisamos de mais bibliotecas.","A leitura é impossível.","Todas as bibliotecas fecharam."],"answer":"B","explanation":"A tese é a posição defendida; a ampliação do acesso é o argumento que a sustenta."},{"authored_id":"interpretacao-19","topic_id":"interpretacao","number":19,"subject":"Português","text":"“Ele quebrou o silêncio ao perguntar pelo irmão.” Nesse contexto, “quebrou o silêncio” significa:","options":["Partiu um objeto.","Desligou o telefone.","Começou a falar.","Deixou de ouvir."],"answer":"C","explanation":"A expressão idiomática indica o início da fala após um período de silêncio."},{"authored_id":"interpretacao-20","topic_id":"interpretacao","number":20,"subject":"Português","text":"Uma campanha diz: “Doe sangue. Uma atitude pode salvar vidas.” O argumento busca:","options":["Provar que qualquer pessoa pode doar sem critérios.","Narrar uma doação específica.","Negar a importância de hospitais.","Persuadir associando a doação ao benefício coletivo."],"answer":"D","explanation":"O imperativo e a consequência positiva incentivam a doação; não eliminam os critérios de elegibilidade."},{"authored_id":"quimica-organica-01","topic_id":"quimica-organica","number":1,"subject":"Química","text":"Qual característica ajuda o carbono a formar grande variedade de compostos?","options":["Formar quatro ligações covalentes e cadeias.","Ser incapaz de ligar-se a outro carbono.","Ter sempre carga positiva.","Só formar ligações iônicas."],"answer":"A","explanation":"A tetravalência e a capacidade de formar cadeias e anéis explicam a diversidade dos compostos de carbono."},{"authored_id":"quimica-organica-02","topic_id":"quimica-organica","number":2,"subject":"Química","text":"Qual grupo caracteriza um álcool, como o etanol?","options":["Carboxila.","Hidroxila ligada a carbono saturado.","Carbonila entre dois carbonos.","Nitrogênio ligado a três oxigênios."],"answer":"B","explanation":"Álcoois apresentam o grupo −OH ligado a carbono saturado; a carboxila caracteriza ácidos carboxílicos."},{"authored_id":"quimica-organica-03","topic_id":"quimica-organica","number":3,"subject":"Química","text":"A fórmula CH₃COOH representa qual função?","options":["Éter.","Amina.","Ácido carboxílico.","Alceno."],"answer":"C","explanation":"O grupo −COOH é a carboxila, característica dos ácidos carboxílicos, como o ácido acético."},{"authored_id":"quimica-organica-04","topic_id":"quimica-organica","number":4,"subject":"Química","text":"Qual grupo caracteriza uma cetona?","options":["Hidroxila em carbono saturado.","Carboxila terminal.","Somente ligações C–C simples sem oxigênio.","Carbonila entre dois carbonos."],"answer":"D","explanation":"Na cetona, o carbono da carbonila liga-se a dois carbonos; no aldeído, liga-se a pelo menos um hidrogênio."},{"authored_id":"quimica-organica-05","topic_id":"quimica-organica","number":5,"subject":"Química","text":"Qual fórmula representa um aldeído?","options":["CH₃CHO.","CH₃COCH₃.","CH₃OH.","CH₃COOH."],"answer":"A","explanation":"CH₃CHO possui carbonila terminal ligada a hidrogênio; as demais fórmulas são cetona, álcool e ácido."},{"authored_id":"quimica-organica-06","topic_id":"quimica-organica","number":6,"subject":"Química","text":"Na estrutura R–O–R′, qual é a função?","options":["Éster.","Éter.","Ácido carboxílico.","Amida."],"answer":"B","explanation":"Éteres possuem oxigênio entre dois grupos carbônicos; ésteres também contêm carbonila adjacente ao oxigênio."},{"authored_id":"quimica-organica-07","topic_id":"quimica-organica","number":7,"subject":"Química","text":"O grupo R–COO–R′ caracteriza:","options":["Alcano.","Aldeído.","Éster.","Amina."],"answer":"C","explanation":"O éster contém carbonila ligada a um oxigênio que também se liga a outro grupo carbônico."},{"authored_id":"quimica-organica-08","topic_id":"quimica-organica","number":8,"subject":"Química","text":"Qual composto é um hidrocarboneto?","options":["Etanol, C₂H₆O.","Ácido acético, C₂H₄O₂.","Ureia, CH₄N₂O.","Propano, C₃H₈."],"answer":"D","explanation":"Hidrocarbonetos contêm apenas carbono e hidrogênio; os demais têm oxigênio ou nitrogênio."},{"authored_id":"quimica-organica-09","topic_id":"quimica-organica","number":9,"subject":"Química","text":"Uma cadeia com ligação dupla entre carbonos é classificada como:","options":["Insaturada.","Obrigatoriamente heterogênea.","Sempre aromática.","Saturada."],"answer":"A","explanation":"Uma ligação dupla ou tripla entre carbonos torna a cadeia insaturada; não basta uma carbonila C=O."},{"authored_id":"quimica-organica-10","topic_id":"quimica-organica","number":10,"subject":"Química","text":"Uma cadeia tem oxigênio entre dois carbonos. Ela é:","options":["Homogênea por definição.","Heterogênea.","Sempre fechada.","Obrigatoriamente aromática."],"answer":"B","explanation":"Um heteroátomo intercalado na cadeia carbônica a torna heterogênea."},{"authored_id":"quimica-organica-11","topic_id":"quimica-organica","number":11,"subject":"Química","text":"Qual é a fórmula molecular do metano?","options":["C₂H₆.","CH₂O.","CH₄.","CO₂."],"answer":"C","explanation":"Metano é o alcano com um carbono e quatro hidrogênios; etano tem dois carbonos."},{"authored_id":"quimica-organica-12","topic_id":"quimica-organica","number":12,"subject":"Química","text":"Qual é a fórmula geral dos alcanos acíclicos?","options":["CₙH₂ₙ.","CₙHₙ.","CₙH₂ₙ₋₂.","CₙH₂ₙ₊₂."],"answer":"D","explanation":"Cadeias abertas com apenas ligações simples entre carbonos têm fórmula CₙH₂ₙ₊₂."},{"authored_id":"quimica-organica-13","topic_id":"quimica-organica","number":13,"subject":"Química","text":"Qual produto é esperado na combustão completa de um hidrocarboneto?","options":["Dióxido de carbono e água.","Somente carbono sólido.","Somente hidrogênio.","Etanol e oxigênio."],"answer":"A","explanation":"Com oxigênio suficiente, o carbono forma CO₂ e o hidrogênio forma H₂O, com liberação de energia."},{"authored_id":"quimica-organica-14","topic_id":"quimica-organica","number":14,"subject":"Química","text":"A combustão incompleta de combustível pode formar:","options":["Somente água pura.","Monóxido de carbono.","Apenas oxigênio.","Sempre glicose."],"answer":"B","explanation":"Oxigênio insuficiente favorece CO e, em certas condições, fuligem, em lugar da oxidação completa a CO₂."},{"authored_id":"quimica-organica-15","topic_id":"quimica-organica","number":15,"subject":"Química","text":"Etanol mistura-se com água principalmente porque:","options":["É um hidrocarboneto apolar puro.","Não possui oxigênio.","Sua hidroxila permite ligações de hidrogênio com a água.","Sempre sofre combustão na água."],"answer":"C","explanation":"O grupo polar −OH interage com água por ligações de hidrogênio, favorecendo a miscibilidade."},{"authored_id":"quimica-organica-16","topic_id":"quimica-organica","number":16,"subject":"Química","text":"Óleo e água tendem a formar duas fases porque:","options":["Ambos são gases.","Água não tem moléculas.","O óleo sempre é mais denso.","O óleo é predominantemente apolar e a água é polar."],"answer":"D","explanation":"As interações entre substâncias de polaridade distinta não favorecem sua mistura; a densidade não explica sozinha a separação."},{"authored_id":"quimica-organica-17","topic_id":"quimica-organica","number":17,"subject":"Química","text":"Dois compostos têm mesma fórmula molecular e estruturas diferentes. Isso é:","options":["Isomeria.","Combustão.","Neutralização obrigatória.","Decantação."],"answer":"A","explanation":"Isômeros compartilham a fórmula molecular, mas diferem na estrutura ou no arranjo espacial."},{"authored_id":"quimica-organica-18","topic_id":"quimica-organica","number":18,"subject":"Química","text":"O benzeno é um exemplo de composto:","options":["Álcool saturado.","Aromático.","Ácido carboxílico.","Proteína."],"answer":"B","explanation":"O benzeno possui anel aromático com elétrons deslocalizados, e não pertence às funções oxigenadas citadas."},{"authored_id":"quimica-organica-19","topic_id":"quimica-organica","number":19,"subject":"Química","text":"A reação entre um ácido carboxílico e um álcool pode produzir:","options":["Somente metano.","Somente sal de cozinha.","Éster e água.","Uma cetona necessariamente."],"answer":"C","explanation":"Na esterificação, ácido e álcool reagem formando éster e água; a reação é reversível."},{"authored_id":"quimica-organica-20","topic_id":"quimica-organica","number":20,"subject":"Química","text":"Qual grupo caracteriza uma amina?","options":["Carboxila.","Hidroxila em carbono saturado.","Oxigênio entre dois carbonos.","Nitrogênio ligado a hidrogênios e/ou grupos carbônicos, sem carbonila diretamente ligada."],"answer":"D","explanation":"Aminas derivam da amônia pela substituição de hidrogênios por grupos orgânicos; carbonila ligada ao nitrogênio caracteriza amida."},{"authored_id":"eletricidade-01","topic_id":"eletricidade","number":1,"subject":"Física","text":"Um resistor de 6 Ω recebe 12 V. Qual é a corrente?","options":["2 A.","72 A.","0,5 A.","18 A."],"answer":"A","explanation":"Pela lei de Ohm, I=V/R=12/6=2 A."},{"authored_id":"eletricidade-02","topic_id":"eletricidade","number":2,"subject":"Física","text":"Uma corrente de 3 A atravessa resistência de 4 Ω. Qual é a tensão?","options":["7 V.","12 V.","0,75 V.","1,33 V."],"answer":"B","explanation":"V=RI=4×3=12 V."},{"authored_id":"eletricidade-03","topic_id":"eletricidade","number":3,"subject":"Física","text":"Resistores de 2 Ω e 4 Ω em série equivalem a:","options":["2 Ω.","8 Ω.","6 Ω.","1,33 Ω."],"answer":"C","explanation":"Em série, as resistências se somam: 2+4=6 Ω."},{"authored_id":"eletricidade-04","topic_id":"eletricidade","number":4,"subject":"Física","text":"Dois resistores de 6 Ω em paralelo equivalem a:","options":["12 Ω.","6 Ω.","36 Ω.","3 Ω."],"answer":"D","explanation":"Dois resistores iguais em paralelo têm resistência equivalente R/2: 6/2=3 Ω."},{"authored_id":"eletricidade-05","topic_id":"eletricidade","number":5,"subject":"Física","text":"Em um circuito em série, a corrente nos componentes é:","options":["A mesma em todos os componentes.","Sempre zero.","Maior apenas no primeiro resistor.","Independente da fonte e da resistência."],"answer":"A","explanation":"Existe um único caminho para as cargas, então a corrente é comum a todos os elementos."},{"authored_id":"eletricidade-06","topic_id":"eletricidade","number":6,"subject":"Física","text":"Em ramos ligados em paralelo à mesma fonte, a tensão é:","options":["Sempre dividida igualmente pelo número de ramos.","A mesma em cada ramo.","Nula no último ramo.","Maior em qualquer resistor menor."],"answer":"B","explanation":"Os ramos compartilham os mesmos dois nós, e por isso têm a mesma diferença de potencial."},{"authored_id":"eletricidade-07","topic_id":"eletricidade","number":7,"subject":"Física","text":"Um aparelho recebe 120 V e corrente de 2 A. Qual é sua potência?","options":["60 W.","122 W.","240 W.","2 W."],"answer":"C","explanation":"Potência elétrica P=VI=120×2=240 W."},{"authored_id":"eletricidade-08","topic_id":"eletricidade","number":8,"subject":"Física","text":"Um aparelho de 1.000 W funciona por 2 horas. Qual é seu consumo?","options":["2.000 kWh.","500 kWh.","1 kWh.","2 kWh."],"answer":"D","explanation":"1.000 W=1 kW. Energia=P×tempo=1×2=2 kWh."},{"authored_id":"eletricidade-09","topic_id":"eletricidade","number":9,"subject":"Física","text":"O kWh mede:","options":["Energia.","Corrente.","Resistência.","Tensão."],"answer":"A","explanation":"É uma unidade de potência multiplicada por tempo, portanto mede energia consumida."},{"authored_id":"eletricidade-10","topic_id":"eletricidade","number":10,"subject":"Física","text":"Um consumo de 10 kWh custa R$ 0,80 por kWh, sem outros encargos. Qual é o custo?","options":["R$ 12,50.","R$ 8,00.","R$ 0,08.","R$ 80,00."],"answer":"B","explanation":"Custo=energia×tarifa=10×0,80=R$ 8,00."},{"authored_id":"eletricidade-11","topic_id":"eletricidade","number":11,"subject":"Física","text":"A função principal de um fusível é:","options":["Aumentar a tensão sempre.","Armazenar energia mecânica.","Interromper o circuito quando a corrente excede seu limite.","Eliminar qualquer consumo."],"answer":"C","explanation":"O elemento do fusível se rompe quando há corrente excessiva, ajudando a proteger o circuito."},{"authored_id":"eletricidade-12","topic_id":"eletricidade","number":12,"subject":"Física","text":"Um chuveiro elétrico aquece a água principalmente pelo:","options":["Efeito Doppler.","Efeito fotoelétrico exclusivamente.","Princípio de Arquimedes.","Efeito Joule."],"answer":"D","explanation":"A passagem de corrente pela resistência transforma energia elétrica em energia térmica."},{"authored_id":"eletricidade-13","topic_id":"eletricidade","number":13,"subject":"Física","text":"Mantendo a tensão em um resistor ôhmico, dobrar a resistência faz a corrente:","options":["Cair à metade.","Dobrar.","Quadruplicar.","Permanecer igual."],"answer":"A","explanation":"I=V/R: com V fixo, corrente e resistência são inversamente proporcionais."},{"authored_id":"eletricidade-14","topic_id":"eletricidade","number":14,"subject":"Física","text":"Mantendo a resistência constante, dobrar a tensão faz a potência dissipada:","options":["Cair à metade.","Quadruplicar.","Permanecer igual.","Dobrar apenas."],"answer":"B","explanation":"P=V²/R. Dobrar V multiplica V² e a potência por quatro."},{"authored_id":"eletricidade-15","topic_id":"eletricidade","number":15,"subject":"Física","text":"Um fio transporta 12 C em 4 s. Qual é a corrente média?","options":["48 A.","16 A.","3 A.","0,33 A."],"answer":"C","explanation":"I=ΔQ/Δt=12/4=3 C/s=3 A."},{"authored_id":"eletricidade-16","topic_id":"eletricidade","number":16,"subject":"Física","text":"A unidade de resistência elétrica é:","options":["Volt.","Ampere.","Watt.","Ohm."],"answer":"D","explanation":"Ohm (Ω) mede resistência; volt mede tensão, ampere corrente e watt potência."},{"authored_id":"eletricidade-17","topic_id":"eletricidade","number":17,"subject":"Física","text":"Um interruptor aberto em série com uma lâmpada ideal faz:","options":["A corrente parar e a lâmpada apagar.","A corrente dobrar.","A resistência da lâmpada desaparecer.","A lâmpada acender sem fonte."],"answer":"A","explanation":"Abrir o interruptor interrompe o caminho condutor, impedindo corrente no circuito."},{"authored_id":"eletricidade-18","topic_id":"eletricidade","number":18,"subject":"Física","text":"Adicionar um resistor em paralelo a outro, mantendo a fonte ideal, faz a resistência equivalente:","options":["Sempre dobrar.","Diminuir.","Ficar infinita.","Permanecer necessariamente igual."],"answer":"B","explanation":"Um caminho adicional aumenta a condutância total; a resistência equivalente fica menor que cada resistência dos ramos."},{"authored_id":"eletricidade-19","topic_id":"eletricidade","number":19,"subject":"Física","text":"Um aparelho de 500 W é usado por 4 horas diárias durante 10 dias. Qual é o consumo?","options":["200 kWh.","2 kWh.","20 kWh.","50 kWh."],"answer":"C","explanation":"500 W=0,5 kW e o tempo total é 40 h. Energia=0,5×40=20 kWh."},{"authored_id":"eletricidade-20","topic_id":"eletricidade","number":20,"subject":"Física","text":"Qual comparação reduz o consumo mantendo o mesmo tempo de funcionamento?","options":["Trocar 20 W por 100 W.","Duplicar o tempo de uso.","Manter potência e tempo iguais.","Trocar um aparelho de 100 W por outro de 20 W."],"answer":"D","explanation":"Energia=P×t. Para mesmo tempo, menor potência significa menor energia consumida."},{"authored_id":"ondas-01","topic_id":"ondas","number":1,"subject":"Física","text":"Uma onda tem velocidade de 340 m/s e frequência de 170 Hz. Qual é seu comprimento?","options":["2 m.","510 m.","0,5 m.","57.800 m."],"answer":"A","explanation":"λ=v/f=340/170=2 m."},{"authored_id":"ondas-02","topic_id":"ondas","number":2,"subject":"Física","text":"Uma onda tem comprimento de 3 m e frequência de 4 Hz. Qual é sua velocidade?","options":["0,75 m/s.","12 m/s.","7 m/s.","1,33 m/s."],"answer":"B","explanation":"v=λf=3×4=12 m/s."},{"authored_id":"ondas-03","topic_id":"ondas","number":3,"subject":"Física","text":"Uma onda tem frequência de 5 Hz. Qual é o período?","options":["5 s.","10 s.","0,2 s.","0,5 s."],"answer":"C","explanation":"T=1/f=1/5=0,2 s."},{"authored_id":"ondas-04","topic_id":"ondas","number":4,"subject":"Física","text":"Qual onda precisa de meio material para se propagar?","options":["Luz visível.","Ondas de rádio.","Raios X.","Som."],"answer":"D","explanation":"Som é onda mecânica; as outras opções são ondas eletromagnéticas que se propagam no vácuo."},{"authored_id":"ondas-05","topic_id":"ondas","number":5,"subject":"Física","text":"Uma onda transporta principalmente:","options":["Energia, sem transporte líquido de matéria no modelo usual.","Toda a matéria do meio junto à frente de onda.","Somente carga elétrica.","Somente massa sólida."],"answer":"A","explanation":"Partículas do meio oscilam em torno de suas posições enquanto a perturbação transmite energia."},{"authored_id":"ondas-06","topic_id":"ondas","number":6,"subject":"Física","text":"No som, a frequência determina principalmente:","options":["A intensidade apenas.","A altura: grave ou agudo.","A velocidade sempre, em qualquer meio.","O volume do recipiente."],"answer":"B","explanation":"Maior frequência corresponde a som mais agudo; intensidade está ligada à energia e à amplitude."},{"authored_id":"ondas-07","topic_id":"ondas","number":7,"subject":"Física","text":"Um som mais intenso, no mesmo contexto, está associado a:","options":["Obrigatoriamente menor frequência.","Ausência de vibração.","Maior amplitude da onda.","Período sempre maior."],"answer":"C","explanation":"A intensidade está relacionada ao quadrado da amplitude; não exige mudança na altura do som."},{"authored_id":"ondas-08","topic_id":"ondas","number":8,"subject":"Física","text":"O eco é associado à:","options":["Polarização obrigatória do som.","Desaparecimento da frequência.","Fusão da fonte.","Reflexão do som."],"answer":"D","explanation":"O som reflete numa superfície e retorna com atraso perceptível ao observador."},{"authored_id":"ondas-09","topic_id":"ondas","number":9,"subject":"Física","text":"Ao passar de um meio para outro, a luz pode mudar de direção. Esse fenômeno é:","options":["Refração.","Apenas reflexão.","Combustão.","Eletrização."],"answer":"A","explanation":"A mudança de velocidade ao atravessar a interface pode alterar a direção da propagação."},{"authored_id":"ondas-10","topic_id":"ondas","number":10,"subject":"Física","text":"Na refração, para uma fonte com frequência fixa, a frequência da onda:","options":["Sempre dobra.","Permanece igual.","Sempre zera.","Muda para igualar o comprimento."],"answer":"B","explanation":"A frequência é determinada pela fonte; velocidade e comprimento de onda se ajustam no novo meio."},{"authored_id":"ondas-11","topic_id":"ondas","number":11,"subject":"Física","text":"Ondas contornando um obstáculo evidenciam:","options":["Somente refração.","Apenas absorção.","Difração.","Corrente elétrica."],"answer":"C","explanation":"Difração é o espalhamento da onda em aberturas e ao redor de obstáculos."},{"authored_id":"ondas-12","topic_id":"ondas","number":12,"subject":"Física","text":"A difração fica mais perceptível quando uma abertura tem largura:","options":["Sempre milhares de vezes maior que o comprimento.","Nula, permitindo passagem normal.","Independente de todas as características da onda.","Próxima do comprimento de onda."],"answer":"D","explanation":"O espalhamento é significativo quando a escala da abertura é comparável à do comprimento de onda."},{"authored_id":"ondas-13","topic_id":"ondas","number":13,"subject":"Física","text":"Duas ondas em fase se superpõem no mesmo ponto. Ocorre:","options":["Interferência construtiva.","Cancelamento total obrigatório.","Ausência de qualquer interferência.","Transformação em partículas materiais."],"answer":"A","explanation":"Em fase, os deslocamentos têm o mesmo sentido e as amplitudes se somam."},{"authored_id":"ondas-14","topic_id":"ondas","number":14,"subject":"Física","text":"Duas ondas de mesma amplitude e em oposição de fase podem gerar:","options":["Sempre o dobro da amplitude.","Interferência destrutiva.","Uma frequência infinita.","Aumento obrigatório da intensidade."],"answer":"B","explanation":"Os deslocamentos opostos podem se cancelar quando as amplitudes são iguais."},{"authored_id":"ondas-15","topic_id":"ondas","number":15,"subject":"Física","text":"Uma ambulância se aproxima de um observador parado. A frequência percebida tende a:","options":["Diminuir.","Ser sempre zero.","Aumentar.","Eliminar a velocidade do som."],"answer":"C","explanation":"No efeito Doppler, a aproximação comprime as frentes de onda e eleva a frequência percebida."},{"authored_id":"ondas-16","topic_id":"ondas","number":16,"subject":"Física","text":"Uma fonte pontual irradia uniformemente sem perdas. Dobrar a distância faz a intensidade:","options":["Dobrar.","Cair à metade apenas.","Quadruplicar.","Cair a um quarto."],"answer":"D","explanation":"I=P/(4πr²). Com distância 2r, a área quadruplica e a intensidade é dividida por quatro."},{"authored_id":"ondas-17","topic_id":"ondas","number":17,"subject":"Física","text":"A polarização evidencia que a luz é uma onda:","options":["Transversal.","Mecânica longitudinal.","Sempre sonora.","Que só existe na água."],"answer":"A","explanation":"Polarização seleciona direções de oscilação perpendiculares à propagação, característica de ondas transversais."},{"authored_id":"ondas-18","topic_id":"ondas","number":18,"subject":"Física","text":"A vibração de uma corda perpendicular à propagação é:","options":["Longitudinal.","Transversal.","Eletromagnética necessariamente.","Estática, sem onda."],"answer":"B","explanation":"Na onda transversal, a oscilação é perpendicular à direção em que a perturbação se propaga."},{"authored_id":"ondas-19","topic_id":"ondas","number":19,"subject":"Física","text":"A ressonância ocorre quando:","options":["A fonte para de vibrar.","Toda onda fica sem energia.","A frequência de excitação se aproxima de uma frequência natural do sistema.","A amplitude precisa ser nula."],"answer":"C","explanation":"A excitação próxima à frequência natural favorece transferência de energia e aumento de amplitude, limitado pelo amortecimento."},{"authored_id":"ondas-20","topic_id":"ondas","number":20,"subject":"Física","text":"Uma onda estacionária resulta tipicamente de:","options":["Uma única partícula parada sem perturbação.","Combustão do meio.","Ausência de reflexão e interferência.","Superposição de ondas de mesma frequência em sentidos opostos."],"answer":"D","explanation":"A superposição produz nós e ventres em posições fixas, caracterizando a onda estacionária."},{"authored_id":"brasil-colonia-01","topic_id":"brasil-colonia","number":1,"subject":"História","text":"Qual objetivo orientou grande parte da colonização portuguesa na América?","options":["Integrar a colônia aos interesses econômicos da metrópole.","Garantir igualdade social imediata.","Proibir exportações agrícolas.","Criar uma república independente desde 1500."],"answer":"A","explanation":"A colonização articulou exploração de recursos, exportação e controle político português."},{"authored_id":"brasil-colonia-02","topic_id":"brasil-colonia","number":2,"subject":"História","text":"A produção açucareira colonial combinava principalmente:","options":["Pequenas propriedades e assalariamento universal.","Latifúndio, monocultura, exportação e trabalho escravizado.","Indústria automobilística e consumo interno.","Agricultura sem comércio externo."],"answer":"B","explanation":"A plantation açucareira vinculava grandes propriedades à demanda externa e à exploração de pessoas escravizadas."},{"authored_id":"brasil-colonia-03","topic_id":"brasil-colonia","number":3,"subject":"História","text":"O pacto colonial estabelecia mecanismos para:","options":["Eliminar toda tributação.","Garantir livre comércio irrestrito à colônia.","Favorecer o controle metropolitano sobre o comércio colonial.","Subordinar Portugal a todos os senhores de engenho."],"answer":"C","explanation":"O exclusivo comercial e outros controles buscavam direcionar ganhos à metrópole, embora houvesse contrabando e negociações."},{"authored_id":"brasil-colonia-04","topic_id":"brasil-colonia","number":4,"subject":"História","text":"Como os povos indígenas reagiram à colonização?","options":["Aceitando todos as imposições sem conflitos.","Desaparecendo antes da chegada portuguesa.","Agindo como um único povo homogêneo.","Por resistências, alianças e estratégias diversas."],"answer":"D","explanation":"Os povos eram diversos e responderam de diferentes formas à violência, às epidemias e às pressões coloniais."},{"authored_id":"brasil-colonia-05","topic_id":"brasil-colonia","number":5,"subject":"História","text":"As missões jesuíticas atuaram na:","options":["Catequese e reorganização da vida indígena.","Defesa universal da autonomia cultural sem interferência.","Criação de partidos republicanos modernos.","Proibição de qualquer conversão religiosa."],"answer":"A","explanation":"A catequese buscava converter indígenas e organizar aldeamentos, com impactos culturais e disputas com colonos."},{"authored_id":"brasil-colonia-06","topic_id":"brasil-colonia","number":6,"subject":"História","text":"Por que a escravidão não deve ser tratada apenas como uma técnica de produção?","options":["Porque não afetou a economia.","Porque estruturou relações sociais, jurídicas e culturais.","Porque inexistiu resistência.","Porque todos os escravizados tinham os mesmos direitos dos senhores."],"answer":"B","explanation":"A escravidão organizou hierarquias, relações de poder e experiências culturais, além de explorar trabalho."},{"authored_id":"brasil-colonia-07","topic_id":"brasil-colonia","number":7,"subject":"História","text":"Quilombos eram:","options":["Somente repartições fiscais.","Instituições criadas para proibir fugas.","Comunidades associadas à resistência à escravidão.","Fábricas de açúcar europeias."],"answer":"C","explanation":"Quilombos reuniam pessoas em busca de autonomia e podiam estabelecer redes econômicas e alianças."},{"authored_id":"brasil-colonia-08","topic_id":"brasil-colonia","number":8,"subject":"História","text":"Qual atitude também constitui resistência de pessoas escravizadas?","options":["Somente aceitar castigos sem reação.","Apoiar exclusivamente o tráfico.","Abolir formalmente a escravidão por decreto próprio.","Preservação cultural e negociação cotidiana."],"answer":"D","explanation":"Resistências incluíam fugas, revoltas, redes de solidariedade, preservação cultural e negociações, com possibilidades limitadas."},{"authored_id":"brasil-colonia-09","topic_id":"brasil-colonia","number":9,"subject":"História","text":"O tráfico atlântico de africanos escravizados foi:","options":["Um sistema lucrativo de violência e deslocamento forçado.","Uma migração voluntária com contratos iguais.","Restrito a uma única origem cultural.","Sem participação de agentes comerciais."],"answer":"A","explanation":"O tráfico mercantilizou pessoas e conectou redes comerciais, com participação de diferentes agentes e consequências humanas profundas."},{"authored_id":"brasil-colonia-10","topic_id":"brasil-colonia","number":10,"subject":"História","text":"A descoberta de ouro no século XVIII contribuiu para:","options":["Fim imediato da escravidão.","Urbanização e maior circulação interna.","Abandono de toda cobrança fiscal.","Desaparecimento das cidades coloniais."],"answer":"B","explanation":"A mineração estimulou núcleos urbanos, abastecimento e circulação de pessoas e mercadorias."},{"authored_id":"brasil-colonia-11","topic_id":"brasil-colonia","number":11,"subject":"História","text":"O quinto correspondia a:","options":["Uma eleição de cinco governadores.","Uma indenização aos indígenas.","Um tributo de 20% sobre o ouro.","Uma taxa de 5% sobre salários industriais."],"answer":"C","explanation":"O nome remete à quinta parte da produção aurífera, apropriada pela Coroa como tributo."},{"authored_id":"brasil-colonia-12","topic_id":"brasil-colonia","number":12,"subject":"História","text":"A derrama era associada à:","options":["Distribuição gratuita de terras.","Abolição de todas as dívidas.","Eleição popular da Coroa.","Cobrança para completar uma meta fiscal de ouro."],"answer":"D","explanation":"Quando a arrecadação não atingia a quota, a cobrança extraordinária podia ser imposta, gerando tensões."},{"authored_id":"brasil-colonia-13","topic_id":"brasil-colonia","number":13,"subject":"História","text":"A Inconfidência Mineira deve ser relacionada a:","options":["Crise colonial, tributação e ideias iluministas.","Defesa consensual da igualdade por toda a população.","Expansão do nazismo.","Implantação imediata de uma democracia universal."],"answer":"A","explanation":"O movimento envolveu setores da elite e projetos diversos no contexto da crise fiscal e da circulação de ideias iluministas."},{"authored_id":"brasil-colonia-14","topic_id":"brasil-colonia","number":14,"subject":"História","text":"A Conjuração Baiana de 1798 destacou-se por:","options":["Defender exclusivamente o aumento do tráfico.","Demandas de liberdade e participação de setores populares.","Acontecer no século XX.","Não ter relação com ideias de igualdade."],"answer":"B","explanation":"O movimento articulou demandas sociais e políticas, incluindo igualdade e abolição, com participação popular."},{"authored_id":"brasil-colonia-15","topic_id":"brasil-colonia","number":15,"subject":"História","text":"As capitanias hereditárias foram uma estratégia para:","options":["Instituir sufrágio universal.","Criar independência imediata de Portugal.","Delegar colonização e administração a donatários.","Substituir o território por províncias industriais."],"answer":"C","explanation":"A Coroa repartiu áreas e delegou atribuições aos donatários, preservando sua soberania."},{"authored_id":"brasil-colonia-16","topic_id":"brasil-colonia","number":16,"subject":"História","text":"A criação do governo-geral buscou:","options":["Extinguir instantaneamente todas as capitanias.","Abolir a escravidão.","Transferir o rei para Brasília.","Coordenar e fortalecer a administração colonial."],"answer":"D","explanation":"O governo-geral centralizou funções administrativas e militares sem eliminar de imediato todas as capitanias."},{"authored_id":"brasil-colonia-17","topic_id":"brasil-colonia","number":17,"subject":"História","text":"As bandeiras contribuíram para a expansão territorial, mas também envolveram:","options":["Captura de indígenas e violência.","Somente pesquisa científica sem conflitos.","Proteção universal aos aldeamentos.","Criação de direitos humanos contemporâneos."],"answer":"A","explanation":"Expedições buscavam mão de obra, metais e outras oportunidades; a captura indígena foi parte importante de muitas delas."},{"authored_id":"brasil-colonia-18","topic_id":"brasil-colonia","number":18,"subject":"História","text":"A invasão holandesa no Nordeste relacionou-se ao:","options":["Controle de fábricas de automóveis.","Interesse no comércio e na produção açucareira.","Fim de toda ligação com o Atlântico.","Projeto de independência brasileiro em 1822."],"answer":"B","explanation":"O açúcar e suas redes comerciais eram centrais à disputa entre potências europeias no Atlântico."},{"authored_id":"brasil-colonia-19","topic_id":"brasil-colonia","number":19,"subject":"História","text":"A transferência da capital para o Rio de Janeiro em 1763 relacionou-se à:","options":["Construção de Brasília.","Proibição de comércio na região mineradora.","Maior importância do Centro-Sul e da mineração.","Extinção da presença portuguesa."],"answer":"C","explanation":"O Rio ganhou relevância como porto e centro administrativo ligado ao ouro e às disputas no sul."},{"authored_id":"brasil-colonia-20","topic_id":"brasil-colonia","number":20,"subject":"História","text":"A sociedade colonial deve ser entendida como:","options":["Igualitária e sem distinções jurídicas.","Composta apenas de portugueses livres.","Sem influência das culturas africanas.","Hierarquizada, com conflitos e diversidade de experiências."],"answer":"D","explanation":"Condição jurídica, origem, riqueza e outros fatores organizavam hierarquias; indígenas e africanos também transformaram a sociedade."},{"authored_id":"imperio-abolicao-01","topic_id":"imperio-abolicao","number":1,"subject":"História","text":"A Independência de 1822 preservou inicialmente:","options":["A monarquia e a escravidão.","O sufrágio universal.","A reforma agrária ampla.","A igualdade jurídica de todas as pessoas."],"answer":"A","explanation":"A ruptura com Portugal não suprimiu a escravidão nem a estrutura monárquica e social."},{"authored_id":"imperio-abolicao-02","topic_id":"imperio-abolicao","number":2,"subject":"História","text":"A Constituição de 1824 estabeleceu:","options":["República federativa.","Monarquia constitucional e Poder Moderador.","Voto universal feminino.","Abolição imediata."],"answer":"B","explanation":"A Carta outorgada organizou quatro poderes e fortaleceu o imperador por meio do Poder Moderador."},{"authored_id":"imperio-abolicao-03","topic_id":"imperio-abolicao","number":3,"subject":"História","text":"O Poder Moderador conferia ao imperador:","options":["Apenas comando religioso sem ação política.","Cargo eleito a cada quatro anos.","Capacidade de intervir no equilíbrio entre os demais poderes.","Obrigação de aceitar todas as decisões provinciais."],"answer":"C","explanation":"Era um instrumento constitucional de centralização, permitindo ações como dissolver a Câmara e nomear senadores."},{"authored_id":"imperio-abolicao-04","topic_id":"imperio-abolicao","number":4,"subject":"História","text":"O voto censitário restringia a participação com base em:","options":["Escolha aleatória universal.","Residência exclusiva em aldeias indígenas.","Igualdade de renda garantida pelo Estado.","Critérios de renda."],"answer":"D","explanation":"Exigências econômicas limitavam o eleitorado e excluíam amplos setores da população."},{"authored_id":"imperio-abolicao-05","topic_id":"imperio-abolicao","number":5,"subject":"História","text":"O período regencial ocorreu porque:","options":["Pedro I abdicou e Pedro II ainda era menor de idade.","O Brasil se tornou uma república estável.","A escravidão acabou em 1831.","A Constituição proibiu qualquer regente."],"answer":"A","explanation":"Após a abdicação de 1831, regentes governaram até a antecipação da maioridade em 1840."},{"authored_id":"imperio-abolicao-06","topic_id":"imperio-abolicao","number":6,"subject":"História","text":"As revoltas regenciais revelam:","options":["Ausência total de conflitos regionais.","Disputas políticas e tensões sociais nas províncias.","Uniformidade dos projetos políticos.","Participação exclusiva do imperador adulto."],"answer":"B","explanation":"Cabanagem, Balaiada, Farroupilha e outras revoltas tiveram causas, participantes e projetos distintos."},{"authored_id":"imperio-abolicao-07","topic_id":"imperio-abolicao","number":7,"subject":"História","text":"O Golpe da Maioridade em 1840 buscou:","options":["Expulsar todos os cafeicultores.","Implantar sufrágio universal.","Antecipar a posse de Pedro II para estabilizar a política.","Encerrar a monarquia."],"answer":"C","explanation":"A antecipação da maioridade foi uma solução política para as disputas da Regência."},{"authored_id":"imperio-abolicao-08","topic_id":"imperio-abolicao","number":8,"subject":"História","text":"A expansão cafeeira no século XIX relacionou-se à:","options":["Produção exclusiva para consumo indígena.","Eliminação instantânea da escravidão.","Ausência de transporte e crédito.","Demanda externa, grandes propriedades e exploração do trabalho."],"answer":"D","explanation":"O café tornou-se central nas exportações e articulou terra, trabalho, transportes e financiamento."},{"authored_id":"imperio-abolicao-09","topic_id":"imperio-abolicao","number":9,"subject":"História","text":"A Lei Eusébio de Queirós, de 1850, determinou:","options":["A proibição do tráfico atlântico de escravizados para o Brasil.","A libertação imediata de todos os escravizados.","A proibição do café.","O voto feminino."],"answer":"A","explanation":"A lei combateu o tráfico transatlântico; a escravidão e o comércio interno de escravizados continuaram."},{"authored_id":"imperio-abolicao-10","topic_id":"imperio-abolicao","number":10,"subject":"História","text":"A Lei de Terras de 1850 favoreceu a concentração porque:","options":["Distribuiu gratuitamente todas as fazendas.","Estabeleceu a compra como principal forma de acesso a terras devolutas.","Garantiu terras a todos os libertos.","Proibiu qualquer propriedade privada."],"answer":"B","explanation":"A exigência de compra limitava o acesso de pessoas pobres e reforçava desigualdades fundiárias."},{"authored_id":"imperio-abolicao-11","topic_id":"imperio-abolicao","number":11,"subject":"História","text":"A Lei do Ventre Livre de 1871:","options":["Libertou imediatamente todos os adultos.","Criou o tráfico atlântico.","Declarou livres filhos de mulheres escravizadas nascidos após a lei, com restrições.","Distribuiu salários iguais a todos."],"answer":"C","explanation":"A lei previa tutela e possibilidades de exploração do trabalho dos chamados ingênuos, limitando seus efeitos imediatos."},{"authored_id":"imperio-abolicao-12","topic_id":"imperio-abolicao","number":12,"subject":"História","text":"A Lei dos Sexagenários de 1885:","options":["Aboliu toda a escravidão sem condições.","Introduziu o trabalho escravizado.","Garantiu aposentadoria universal.","Previa liberdade para escravizados idosos sob condições."],"answer":"D","explanation":"A lei tinha alcance limitado por idade e exigências de prestação de serviços em determinadas situações."},{"authored_id":"imperio-abolicao-13","topic_id":"imperio-abolicao","number":13,"subject":"História","text":"A Lei Áurea, de 1888, promoveu:","options":["A extinção legal da escravidão.","Uma reforma agrária nacional.","Reparação econômica universal aos libertos.","O fim imediato do racismo."],"answer":"A","explanation":"A lei encerrou juridicamente a escravidão, mas não instituiu políticas amplas de inclusão, terras e reparação."},{"authored_id":"imperio-abolicao-14","topic_id":"imperio-abolicao","number":14,"subject":"História","text":"O movimento abolicionista contou com:","options":["Somente a princesa Isabel.","Pessoas escravizadas, libertos e diversos setores da sociedade.","Apenas comerciantes de escravizados.","Nenhuma participação popular."],"answer":"B","explanation":"Fugas, mobilização, imprensa, redes de apoio e pressão política fizeram parte da luta pela abolição."},{"authored_id":"imperio-abolicao-15","topic_id":"imperio-abolicao","number":15,"subject":"História","text":"Após a abolição, as desigualdades persistiram principalmente porque:","options":["Todos receberam terras iguais.","O racismo foi eliminado imediatamente.","A liberdade legal não veio acompanhada de inclusão social ampla.","A população liberta recusou todo trabalho por natureza."],"answer":"C","explanation":"Exclusão de terra, educação e direitos, associada ao racismo, limitou oportunidades dos libertos e descendentes."},{"authored_id":"imperio-abolicao-16","topic_id":"imperio-abolicao","number":16,"subject":"História","text":"A imigração para áreas cafeeiras relacionou-se à:","options":["Extinção de todos os conflitos trabalhistas.","Proibição do trabalho assalariado.","Fim das exportações de café.","Busca de trabalho e reorganização das relações de produção."],"answer":"D","explanation":"A transição envolveu diferentes sistemas de trabalho, incentivos à imigração e conflitos com proprietários."},{"authored_id":"imperio-abolicao-17","topic_id":"imperio-abolicao","number":17,"subject":"História","text":"As ferrovias no contexto cafeeiro favoreceram:","options":["O transporte da produção aos portos.","A proibição de exportações.","O isolamento completo do interior.","A eliminação da concentração fundiária."],"answer":"A","explanation":"As ferrovias reduziram custos e integraram áreas produtoras às redes de exportação."},{"authored_id":"imperio-abolicao-18","topic_id":"imperio-abolicao","number":18,"subject":"História","text":"A Guerra do Paraguai contribuiu no Brasil para:","options":["Abolir automaticamente a monarquia em 1870.","Fortalecer o Exército como ator político.","Extinguir todos os gastos públicos.","Impedir qualquer mobilização militar."],"answer":"B","explanation":"A guerra ampliou o protagonismo militar e reforçou tensões posteriores com o governo imperial."},{"authored_id":"imperio-abolicao-19","topic_id":"imperio-abolicao","number":19,"subject":"História","text":"A crise do Império envolveu:","options":["Um único evento sem conflitos anteriores.","Sufrágio universal consolidado.","Questões militares, religiosas e escravistas, entre outros fatores.","Ausência de movimentos republicanos."],"answer":"C","explanation":"A queda da monarquia resultou da combinação de tensões e perda de apoio político, sem causa única."},{"authored_id":"imperio-abolicao-20","topic_id":"imperio-abolicao","number":20,"subject":"História","text":"A República foi proclamada em 1889 por:","options":["Um plebiscito de toda a população.","Uma decisão da Assembleia colonial em 1500.","Uma votação feminina universal.","Um movimento com liderança militar."],"answer":"D","explanation":"A ação liderada por militares derrubou a monarquia; não houve consulta popular universal."},{"authored_id":"republica-vargas-01","topic_id":"republica-vargas","number":1,"subject":"História","text":"A Constituição de 1891 instituiu:","options":["República federativa e presidencialismo.","Poder Moderador imperial.","Monarquia hereditária.","Voto universal sem restrições."],"answer":"A","explanation":"A nova Constituição organizou o federalismo e a presidência, mantendo exclusões na participação eleitoral."},{"authored_id":"republica-vargas-02","topic_id":"republica-vargas","number":2,"subject":"História","text":"O coronelismo relacionava-se a:","options":["Democracia direta sem coerção.","Poder local, dependência social e controle eleitoral.","Apenas uma patente militar formal.","Fim das desigualdades rurais."],"answer":"B","explanation":"Chefes locais combinavam influência econômica, clientelismo e relações com governos para controlar votos."},{"authored_id":"republica-vargas-03","topic_id":"republica-vargas","number":3,"subject":"História","text":"O voto de cabresto caracterizava:","options":["Voto secreto plenamente protegido.","Eleição por sorteio.","Coerção e controle sobre o voto de eleitores.","Participação universal livre de pressões."],"answer":"C","explanation":"Dependência e ameaças, favorecidas pelo voto aberto, limitavam a autonomia dos eleitores."},{"authored_id":"republica-vargas-04","topic_id":"republica-vargas","number":4,"subject":"História","text":"A política dos governadores buscava:","options":["Eliminar toda influência oligárquica.","Restaurar Portugal no Brasil.","Garantir oposição majoritária em todos os estados.","Articular apoio entre governos estaduais e federal."],"answer":"D","explanation":"A troca de apoio ajudava a sustentar oligarquias e maiorias governistas, com mecanismos de exclusão da oposição."},{"authored_id":"republica-vargas-05","topic_id":"republica-vargas","number":5,"subject":"História","text":"A expressão “café com leite” refere-se à:","options":["Forte influência das elites de São Paulo e Minas Gerais.","Alternância automática e sem exceções em todas as eleições.","Proibição do café.","Igualdade de poder de todos os estados."],"answer":"A","explanation":"A expressão sintetiza uma aliança importante, mas não explica todas as disputas ou sucessões do período."},{"authored_id":"republica-vargas-06","topic_id":"republica-vargas","number":6,"subject":"História","text":"A valorização do café buscava:","options":["Eliminar a cafeicultura.","Sustentar preços com intervenção pública sobre estoques e oferta.","Reduzir preços obrigatoriamente a zero.","Redistribuir todas as fazendas."],"answer":"B","explanation":"A compra e retenção de excedentes procuravam limitar a queda de preços e proteger produtores."},{"authored_id":"republica-vargas-07","topic_id":"republica-vargas","number":7,"subject":"História","text":"A Guerra de Canudos revela:","options":["Uma greve industrial em São Paulo.","Uma eleição presidencial pacífica.","Conflitos sociais e violência estatal contra uma comunidade sertaneja.","Um movimento organizado em 1988."],"answer":"C","explanation":"A comunidade liderada por Antônio Conselheiro enfrentou expedições militares num contexto de pobreza e tensões com autoridades."},{"authored_id":"republica-vargas-08","topic_id":"republica-vargas","number":8,"subject":"História","text":"A Revolta da Vacina de 1904 envolveu:","options":["Somente oposição científica à existência de microrganismos.","Luta pela independência de Portugal.","Fim do governo Vargas.","Resistência a medidas autoritárias e tensões urbanas, além da vacinação obrigatória."],"answer":"D","explanation":"Reformas urbanas, remoções e a imposição da vacinação contribuíram para a revolta; sua causa não se reduz ao imunizante."},{"authored_id":"republica-vargas-09","topic_id":"republica-vargas","number":9,"subject":"História","text":"O tenentismo defendia, em linhas gerais:","options":["Críticas ao domínio oligárquico e reformas políticas.","Restauração consensual do absolutismo.","Manutenção de todas as fraudes eleitorais.","Ausência de intervenção militar na política."],"answer":"A","explanation":"Setores de jovens oficiais contestaram a ordem oligárquica, embora seus projetos e práticas fossem diversos."},{"authored_id":"republica-vargas-10","topic_id":"republica-vargas","number":10,"subject":"História","text":"A crise de 1929 afetou o Brasil ao:","options":["Eliminar toda ligação com o comércio exterior.","Reduzir demanda e preços do café exportado.","Criar imediatamente pleno emprego.","Aumentar automaticamente todos os preços do café."],"answer":"B","explanation":"A depressão internacional atingiu a economia exportadora e agravou tensões políticas e sociais."},{"authored_id":"republica-vargas-11","topic_id":"republica-vargas","number":11,"subject":"História","text":"O movimento de 1930 levou:","options":["Pedro II ao trono.","À Constituição de 1988.","Vargas ao poder e à ruptura com a sucessão da República Velha.","Ao Estado Novo já em 1922."],"answer":"C","explanation":"Vargas assumiu após a deposição de Washington Luís e o impedimento da posse de Júlio Prestes."},{"authored_id":"republica-vargas-12","topic_id":"republica-vargas","number":12,"subject":"História","text":"A Revolução Constitucionalista de 1932 defendia principalmente:","options":["Abolição da escravidão ainda vigente.","Retorno do pacto colonial.","Fim de toda constituição.","Constitucionalização e contestação ao governo provisório."],"answer":"D","explanation":"Setores paulistas se insurgiram contra Vargas, articulando demandas de constituição e disputas por poder."},{"authored_id":"republica-vargas-13","topic_id":"republica-vargas","number":13,"subject":"História","text":"A Constituição de 1934 reconheceu:","options":["Direitos trabalhistas e avanços na participação política.","A escravidão como regra.","Monarquia hereditária.","Fim de toda eleição."],"answer":"A","explanation":"A Carta incorporou direitos sociais e o voto feminino já instituído em 1932, mantendo limites sociais e políticos."},{"authored_id":"republica-vargas-14","topic_id":"republica-vargas","number":14,"subject":"História","text":"O Estado Novo começou em 1937 por meio de:","options":["Uma eleição presidencial livre vencida por Vargas.","Um golpe que instaurou uma ditadura.","Um plebiscito universal sobre o café.","Uma decisão da Coroa portuguesa."],"answer":"B","explanation":"Vargas fechou o Congresso e impôs uma nova Constituição, ampliando a centralização autoritária."},{"authored_id":"republica-vargas-15","topic_id":"republica-vargas","number":15,"subject":"História","text":"O Departamento de Imprensa e Propaganda atuava na:","options":["Garantia irrestrita de liberdade de imprensa.","Administração exclusiva de ferrovias.","Propaganda governamental e censura.","Organização da abolição de 1888."],"answer":"C","explanation":"O DIP construiu a imagem do governo e controlou manifestações culturais e meios de comunicação."},{"authored_id":"republica-vargas-16","topic_id":"republica-vargas","number":16,"subject":"História","text":"A imagem de Vargas como “pai dos pobres” relacionava-se à:","options":["Ausência completa de repressão.","Igualdade econômica efetiva para todos.","Extinção do poder presidencial.","Política trabalhista e propaganda de aproximação com trabalhadores."],"answer":"D","explanation":"Direitos e retórica de proteção social coexistiram com controle sindical e autoritarismo."},{"authored_id":"republica-vargas-17","topic_id":"republica-vargas","number":17,"subject":"História","text":"A CLT, de 1943, teve como objetivo:","options":["Consolidar normas trabalhistas.","Criar voto de cabresto.","Abolir o trabalho urbano.","Garantir inicialmente todos os direitos a todos os trabalhadores rurais."],"answer":"A","explanation":"A consolidação reuniu leis do trabalho, com foco urbano e limitações de alcance, sem universalização imediata."},{"authored_id":"republica-vargas-18","topic_id":"republica-vargas","number":18,"subject":"História","text":"O controle sindical varguista incluía:","options":["Autonomia total sem interferência.","Vinculação de sindicatos ao Estado e limites à autonomia.","Proibição permanente de qualquer sindicato em todo o período.","Exclusão do Estado de relações trabalhistas."],"answer":"B","explanation":"O reconhecimento estatal e a intervenção limitaram a ação sindical independente."},{"authored_id":"republica-vargas-19","topic_id":"republica-vargas","number":19,"subject":"História","text":"A industrialização varguista foi favorecida por:","options":["Proibição de indústria nacional.","Retorno exclusivo à economia colonial.","Intervenção estatal e investimentos em setores de base.","Fim de infraestrutura e crédito."],"answer":"C","explanation":"O Estado incentivou infraestrutura e indústria de base, como siderurgia, em um processo que também envolveu capital privado."},{"authored_id":"republica-vargas-20","topic_id":"republica-vargas","number":20,"subject":"História","text":"A queda de Vargas em 1945 relacionou-se à:","options":["Fim do Império em 1889.","Criação do regime militar de 1964.","Ausência de oposição política.","Pressão pela democratização após a guerra e ação militar."],"answer":"D","explanation":"O contexto antifascista e a mobilização interna tornaram contraditória a continuidade da ditadura, encerrada com sua deposição."},{"authored_id":"ditadura-redemocratizacao-01","topic_id":"ditadura-redemocratizacao","number":1,"subject":"História","text":"O golpe de 1964 resultou na:","options":["Deposição de João Goulart e início do regime militar.","Posse direta de Tancredo Neves.","Promulgação imediata da Constituição de 1988.","Restauração do Império."],"answer":"A","explanation":"A ruptura interrompeu o governo Goulart e inaugurou um regime autoritário com participação militar e apoios civis."},{"authored_id":"ditadura-redemocratizacao-02","topic_id":"ditadura-redemocratizacao","number":2,"subject":"História","text":"Os atos institucionais serviam para:","options":["Garantir eleições diretas irrestritas.","Ampliar poderes do regime e restringir direitos.","Eliminar toda censura.","Transferir a presidência a sindicatos."],"answer":"B","explanation":"Os atos criaram instrumentos de exceção, cassações e outras restrições à ordem constitucional."},{"authored_id":"ditadura-redemocratizacao-03","topic_id":"ditadura-redemocratizacao","number":3,"subject":"História","text":"O AI-5, de 1968, marcou:","options":["A adoção do voto universal livre.","O fim imediato da ditadura.","O aprofundamento da repressão e do autoritarismo.","A criação do SUS."],"answer":"C","explanation":"O AI-5 ampliou poderes excepcionais, permitiu fechamento do Congresso e suspendeu garantias para crimes políticos."},{"authored_id":"ditadura-redemocratizacao-04","topic_id":"ditadura-redemocratizacao","number":4,"subject":"História","text":"A censura no regime militar buscava:","options":["Garantir liberdade plena da imprensa.","Proteger exclusivamente direitos de artistas.","Organizar eleições livres.","Controlar informações e manifestações críticas."],"answer":"D","explanation":"Meios de comunicação e produções culturais sofreram cortes e restrições por razões políticas."},{"authored_id":"ditadura-redemocratizacao-05","topic_id":"ditadura-redemocratizacao","number":5,"subject":"História","text":"A tortura praticada por agentes estatais constitui:","options":["Violação de direitos humanos.","Procedimento democrático de debate.","Direito eleitoral universal.","Ação sem consequências humanas."],"answer":"A","explanation":"A tortura viola integridade e dignidade e foi parte dos mecanismos repressivos do regime."},{"authored_id":"ditadura-redemocratizacao-06","topic_id":"ditadura-redemocratizacao","number":6,"subject":"História","text":"O bipartidarismo imposto pelo regime organizou principalmente:","options":["PT e PSDB desde 1964.","ARENA e MDB.","Liberais e conservadores imperiais.","Um sistema sem qualquer partido formal."],"answer":"B","explanation":"A ARENA apoiava o regime; o MDB reunia oposição consentida, sob limites e vigilância."},{"authored_id":"ditadura-redemocratizacao-07","topic_id":"ditadura-redemocratizacao","number":7,"subject":"História","text":"O “milagre econômico” combinou:","options":["Igualdade social automática.","Ausência de empréstimos externos.","Crescimento elevado com concentração de renda e endividamento.","Recessão contínua em todos os seus anos."],"answer":"C","explanation":"O crescimento não se traduziu em distribuição igualitária e foi acompanhado por desequilíbrios e maior dívida."},{"authored_id":"ditadura-redemocratizacao-08","topic_id":"ditadura-redemocratizacao","number":8,"subject":"História","text":"A propaganda “Brasil: ame-o ou deixe-o” expressava:","options":["Proteção irrestrita à oposição.","Incentivo ao pluralismo de ideias.","Uma campanha da Independência de 1822.","Nacionalismo usado para deslegitimar críticas ao regime."],"answer":"D","explanation":"A propaganda associava patriotismo ao apoio ao governo e hostilizava contestadores."},{"authored_id":"ditadura-redemocratizacao-09","topic_id":"ditadura-redemocratizacao","number":9,"subject":"História","text":"A abertura “lenta, gradual e segura” pretendia:","options":["Controlar a transição política a partir do governo.","Entregar imediatamente o poder por voto direto.","Restaurar o tráfico atlântico.","Extinguir todas as instituições civis."],"answer":"A","explanation":"A abertura iniciada sob Geisel buscava conduzir mudanças mantendo controle e proteção aos interesses do regime."},{"authored_id":"ditadura-redemocratizacao-10","topic_id":"ditadura-redemocratizacao","number":10,"subject":"História","text":"As greves do ABC no final dos anos 1970 foram importantes por:","options":["Eliminar os sindicatos.","Reorganizar mobilização trabalhista e oposição política.","Apoiar exclusivamente o AI-5.","Impedir qualquer reivindicação salarial."],"answer":"B","explanation":"A mobilização por salários e direitos ampliou a participação social e produziu novas lideranças políticas."},{"authored_id":"ditadura-redemocratizacao-11","topic_id":"ditadura-redemocratizacao","number":11,"subject":"História","text":"A Lei da Anistia de 1979 permitiu:","options":["A eleição direta de todos os presidentes desde 1979.","O fim de todo debate sobre o passado.","O retorno de muitos exilados e gerou disputas sobre responsabilização.","A criação automática da Constituição de 1988."],"answer":"C","explanation":"A lei viabilizou retornos e restituição de direitos em certos casos; seu alcance quanto a agentes repressivos permaneceu controverso."},{"authored_id":"ditadura-redemocratizacao-12","topic_id":"ditadura-redemocratizacao","number":12,"subject":"História","text":"A campanha Diretas Já reivindicava:","options":["Retorno da monarquia.","Continuidade obrigatória do AI-5.","Fim do voto popular em todos os cargos.","Eleições diretas para presidente."],"answer":"D","explanation":"A campanha de 1983–1984 mobilizou amplos setores pela escolha direta do presidente."},{"authored_id":"ditadura-redemocratizacao-13","topic_id":"ditadura-redemocratizacao","number":13,"subject":"História","text":"A emenda Dante de Oliveira, em 1984:","options":["Não obteve os votos necessários para ser aprovada.","Instalou imediatamente eleição direta presidencial.","Aboliu todas as eleições estaduais.","Criou a ditadura em 1964."],"answer":"A","explanation":"Sua rejeição manteve a escolha presidencial seguinte pelo Colégio Eleitoral."},{"authored_id":"ditadura-redemocratizacao-14","topic_id":"ditadura-redemocratizacao","number":14,"subject":"História","text":"Tancredo Neves foi eleito em 1985:","options":["Por sufrágio direto universal.","Indiretamente pelo Colégio Eleitoral.","Pela Assembleia colonial.","Por hereditariedade."],"answer":"B","explanation":"A eleição indireta foi parte da transição negociada; Tancredo não chegou a tomar posse."},{"authored_id":"ditadura-redemocratizacao-15","topic_id":"ditadura-redemocratizacao","number":15,"subject":"História","text":"José Sarney assumiu a presidência em 1985 porque:","options":["Venceu uma eleição direta naquele ano.","Foi proclamado imperador.","Era o vice eleito e Tancredo não tomou posse, vindo a falecer.","Era presidente em 1964."],"answer":"C","explanation":"A doença e depois a morte de Tancredo levaram o vice Sarney a exercer a presidência."},{"authored_id":"ditadura-redemocratizacao-16","topic_id":"ditadura-redemocratizacao","number":16,"subject":"História","text":"A Constituição de 1988 ficou conhecida como “Cidadã” porque:","options":["Restaurou o Poder Moderador.","Eliminou direitos sociais.","Garantiu o fim imediato de todas as desigualdades.","Ampliou direitos e mecanismos democráticos."],"answer":"D","explanation":"A Carta reconheceu direitos civis, políticos e sociais; sua efetivação continua a depender de políticas e disputas."},{"authored_id":"ditadura-redemocratizacao-17","topic_id":"ditadura-redemocratizacao","number":17,"subject":"História","text":"O SUS relaciona-se ao princípio constitucional de:","options":["Saúde como direito de todos e dever do Estado.","Atendimento apenas para empregados com carteira.","Exclusão obrigatória de pessoas pobres.","Privatização constitucional de todos os hospitais."],"answer":"A","explanation":"A Constituição de 1988 estabeleceu acesso universal e bases para o sistema público de saúde."},{"authored_id":"ditadura-redemocratizacao-18","topic_id":"ditadura-redemocratizacao","number":18,"subject":"História","text":"A eleição presidencial de 1989 marcou:","options":["A primeira eleição da República em 1889.","O retorno da escolha direta após o regime militar.","A posse de Vargas.","O início do AI-5."],"answer":"B","explanation":"A eleição de 1989 retomou a votação popular direta para presidente, após longo intervalo."},{"authored_id":"ditadura-redemocratizacao-19","topic_id":"ditadura-redemocratizacao","number":19,"subject":"História","text":"Movimentos sociais durante a redemocratização:","options":["Não tiveram participação política.","Existiram somente no século XIX.","Pressionaram por direitos e participaram dos debates constituintes.","Defenderam unanimemente censura permanente."],"answer":"C","explanation":"Organizações populares, sindicais e outras mobilizações influenciaram agendas e propostas na transição."},{"authored_id":"ditadura-redemocratizacao-20","topic_id":"ditadura-redemocratizacao","number":20,"subject":"História","text":"Estudar memória e justiça sobre a ditadura permite:","options":["Apagar todas as fontes históricas.","Tratar todo testemunho como irrelevante.","Concluir que a repressão não existiu.","Compreender violações e discutir responsabilização e reparação."],"answer":"D","explanation":"Documentos e testemunhos ajudam a reconstruir experiências e fundamentar debates democráticos sobre o passado."},{"authored_id":"idade-media-01","topic_id":"idade-media","number":1,"subject":"História","text":"A periodização tradicional situa a Idade Média europeia entre:","options":["Os séculos V e XV.","Os séculos XVIII e XX.","1500 e 1800 exclusivamente.","A Revolução Francesa e a Segunda Guerra."],"answer":"A","explanation":"Convencionalmente, 476 e 1453 marcam limites; periodizações são construções históricas e variam conforme a abordagem."},{"authored_id":"idade-media-02","topic_id":"idade-media","number":2,"subject":"História","text":"A queda do Império Romano do Ocidente ocorreu tradicionalmente em:","options":["1453.","476.","1789.","1822."],"answer":"B","explanation":"476 é a data convencional associada à deposição de Rômulo Augústulo, marco da periodização europeia."},{"authored_id":"idade-media-03","topic_id":"idade-media","number":3,"subject":"História","text":"A Alta Idade Média foi marcada pela:","options":["Revolução Industrial.","Criação de Estados nacionais plenamente modernos em toda a Europa.","Formação de reinos germânicos e ruralização.","Extinção imediata da Igreja."],"answer":"C","explanation":"Fragmentação política e reorganização rural contribuíram para a formação das relações medievais."},{"authored_id":"idade-media-04","topic_id":"idade-media","number":4,"subject":"História","text":"Carlos Magno está associado ao:","options":["Império brasileiro.","Império otomano de 1453.","Governo de Vargas.","Império Carolíngio."],"answer":"D","explanation":"O rei franco ampliou territórios e foi coroado imperador em 800, articulando poder político e Igreja."},{"authored_id":"idade-media-05","topic_id":"idade-media","number":5,"subject":"História","text":"O feudo tinha papel central porque:","options":["A terra sustentava produção e relações de poder.","A indústria mecanizada era a base econômica.","Todos viviam exclusivamente de salários urbanos.","Não existia agricultura."],"answer":"A","explanation":"A posse e o uso da terra organizavam a economia agrária e as obrigações sociais."},{"authored_id":"idade-media-06","topic_id":"idade-media","number":6,"subject":"História","text":"Na representação das três ordens, o clero tinha a função de:","options":["Trabalhar exclusivamente em fábricas.","Rezar e cuidar da vida religiosa.","Administrar sindicatos modernos.","Ser obrigatoriamente servo da terra."],"answer":"B","explanation":"O modelo de ordens atribuía funções de oração, guerra e trabalho; não descrevia toda a diversidade social."},{"authored_id":"idade-media-07","topic_id":"idade-media","number":7,"subject":"História","text":"A suserania e vassalagem era uma relação principalmente entre:","options":["Somente servos e operários industriais.","Todos os cidadãos com voto universal.","Nobres, baseada em fidelidade e obrigações.","Consumidores e bancos digitais."],"answer":"C","explanation":"O vínculo incluía concessões e deveres de apoio, especialmente militar, entre membros da nobreza."},{"authored_id":"idade-media-08","topic_id":"idade-media","number":8,"subject":"História","text":"A servidão medieval caracterizava-se por:","options":["Igualdade jurídica plena com a nobreza.","Livre contrato salarial universal.","Identidade completa com todas as formas de escravidão.","Vinculação à terra e obrigações ao senhor."],"answer":"D","explanation":"Servos tinham obrigações e mobilidade limitada; servidão e escravidão são relações históricas distintas."},{"authored_id":"idade-media-09","topic_id":"idade-media","number":9,"subject":"História","text":"A corveia correspondia ao:","options":["Trabalho obrigatório em terras senhoriais.","Uso pago de forno apenas.","Voto do camponês.","Comércio marítimo livre."],"answer":"A","explanation":"A corveia exigia dias de trabalho na reserva do senhor, além do trabalho do servo em sua parcela."},{"authored_id":"idade-media-10","topic_id":"idade-media","number":10,"subject":"História","text":"As banalidades eram:","options":["Doações obrigatórias de terras ao rei.","Cobranças pelo uso de instalações senhoriais.","Eleições anuais de cavaleiros.","Impostos industriais contemporâneos."],"answer":"B","explanation":"Moinhos, fornos e outras instalações podiam ser utilizados mediante pagamento ao senhor."},{"authored_id":"idade-media-11","topic_id":"idade-media","number":11,"subject":"História","text":"A talha correspondia à:","options":["Libertação automática do servo.","Compra de títulos universitários.","Entrega de parte da produção ao senhor.","Prestação de serviço militar entre reis."],"answer":"C","explanation":"Era uma obrigação em produtos que retirava parcela da colheita camponesa."},{"authored_id":"idade-media-12","topic_id":"idade-media","number":12,"subject":"História","text":"A Igreja medieval exercia:","options":["Apenas atividades sem relação com a sociedade.","Nenhuma posse de terras.","Defesa universal da ciência moderna já consolidada.","Influência religiosa, política, econômica e cultural."],"answer":"D","explanation":"A Igreja possuía terras, influenciava governantes e participava da educação e da cultura letrada."},{"authored_id":"idade-media-13","topic_id":"idade-media","number":13,"subject":"História","text":"A expansão agrícola da Baixa Idade Média foi favorecida por:","options":["Inovações como charrua e rotação de culturas.","Uso generalizado de tratores a diesel.","Abandono de toda técnica agrícola.","Proibição da produção de alimentos."],"answer":"A","explanation":"Técnicas e expansão de áreas cultivadas ajudaram a aumentar produção, embora com diferenças regionais."},{"authored_id":"idade-media-14","topic_id":"idade-media","number":14,"subject":"História","text":"As Cruzadas tinham como objetivo declarado:","options":["Independência do Brasil.","Retomar lugares sagrados sob domínio muçulmano.","Abolir toda a religião cristã.","Industrializar a América."],"answer":"B","explanation":"As expedições envolveram motivações religiosas, políticas e econômicas e aprofundaram contatos e conflitos."},{"authored_id":"idade-media-15","topic_id":"idade-media","number":15,"subject":"História","text":"O crescimento de burgos contribuiu para:","options":["O desaparecimento imediato da agricultura.","A implantação de fábricas digitais.","A expansão de comerciantes e artesãos urbanos.","O fim universal dos reis."],"answer":"C","explanation":"As cidades e o comércio ampliaram a atuação de grupos urbanos chamados de burguesia."},{"authored_id":"idade-media-16","topic_id":"idade-media","number":16,"subject":"História","text":"As corporações de ofício regulavam:","options":["Somente expedições militares.","A vacinação contra a peste.","Eleições presidenciais.","Produção e aprendizagem de atividades artesanais."],"answer":"D","explanation":"As corporações organizavam mestres, oficiais e aprendizes, com regras sobre qualidade e exercício do ofício."},{"authored_id":"idade-media-17","topic_id":"idade-media","number":17,"subject":"História","text":"A Escolástica procurava:","options":["Articular a fé cristã e a razão filosófica.","Eliminar qualquer estudo religioso.","Criar o método industrial fordista.","Impedir o surgimento de universidades."],"answer":"A","explanation":"Pensadores como Tomás de Aquino relacionaram a teologia à filosofia, especialmente aristotélica."},{"authored_id":"idade-media-18","topic_id":"idade-media","number":18,"subject":"História","text":"O estilo gótico destacou-se por:","options":["Apenas paredes sem aberturas e sem altura.","Verticalidade, arcos ogivais e vitrais.","Uso exclusivo de concreto industrial moderno.","Ausência de arquitetura religiosa."],"answer":"B","explanation":"Recursos estruturais como arcos e arcobotantes permitiram edifícios altos e amplas janelas com vitrais."},{"authored_id":"idade-media-19","topic_id":"idade-media","number":19,"subject":"História","text":"A crise do século XIV combinou:","options":["Somente uma mudança de rei.","Prosperidade sem interrupções.","Fome, epidemias e guerras.","A Revolução Industrial e a internet."],"answer":"C","explanation":"Problemas agrícolas, a Peste Negra e conflitos agravaram a crise e transformaram relações sociais e econômicas."},{"authored_id":"idade-media-20","topic_id":"idade-media","number":20,"subject":"História","text":"A Peste Negra contribuiu para transformações do feudalismo porque:","options":["Extinguiu instantaneamente todos os feudos.","Criou imediatamente democracias em toda a Europa.","Não afetou relações de produção.","A mortalidade alterou a oferta de trabalho e agravou tensões sociais."],"answer":"D","explanation":"A escassez de trabalhadores e as disputas por obrigações e remuneração contribuíram para mudanças, com trajetórias regionais distintas."}]$questions$::jsonb)
as q(authored_id text,topic_id text,number integer,subject text,text text,options jsonb,answer text,explanation text)
on conflict (authored_id) do update set topic_id=excluded.topic_id,number=excluded.number,subject=excluded.subject,text=excluded.text,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;